{
  "name": "PDF Summarizer AI",
  "description": "Uma aplicação moderna para resumir arquivos PDF locais usando a inteligência artificial do Google Gemini. Basta arrastar e soltar seu documento."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AppState {
  IDLE = 'IDLE',
  PROCESSING = 'PROCESSING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

export interface SummaryResult {
  text: string;
}

export interface ProcessingError {
  message: string;
  details?: string;
}

/**
 * Converts a File object to a Base64 string suitable for Gemini API.
 * It strips the data URL prefix (e.g., "data:application/pdf;base64,").
 */
export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      if (typeof reader.result === 'string') {
        // Remove the Data URL prefix to get just the base64 string
        const base64String = reader.result.split(',')[1];
        resolve(base64String);
      } else {
        reject(new Error('Failed to convert file to base64.'));
      }
    };
    reader.onerror = (error) => reject(error);
  });
};

import { GoogleGenAI } from "@google/genai";

// Ensure API key is available
if (!process.env.API_KEY) {
  console.error("API_KEY is missing from environment variables.");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Sends a PDF base64 string to Gemini and requests a summary.
 */
export const summarizePdf = async (base64Pdf: string, fileName: string): Promise<string> => {
  try {
    const modelId = 'gemini-2.5-flash-latest'; // Using Flash for efficiency with documents

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'application/pdf',
              data: base64Pdf
            }
          },
          {
            text: `Por favor, analise o documento PDF anexado ("${fileName}"). 

            Crie um resumo detalhado e estruturado em Markdown, seguindo este formato:

            # Título do Documento (detectado ou gerado)

            ## Resumo Executivo
            Uma breve visão geral do conteúdo (2-3 parágrafos).

            ## Pontos Principais
            - Liste os pontos cruciais em tópicos.

            ## Conclusão
            Uma sentença final sobre a importância ou objetivo do documento.

            Use português do Brasil.`
          }
        ]
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("A resposta da IA estava vazia.");
    }

    return text;

  } catch (error: any) {
    console.error("Gemini API Error:", error);
    let errorMessage = "Ocorreu um erro ao processar o documento.";

    if (error.message) {
      if (error.message.includes("API key")) {
        errorMessage = "Chave de API inválida ou ausente.";
      } else if (error.message.includes("429")) {
        errorMessage = "Limite de requisições excedido. Tente novamente em alguns instantes.";
      } else {
        errorMessage = error.message;
      }
    }

    throw new Error(errorMessage);
  }
};

import React, { useCallback, useState } from 'react';
import { Upload, FileText, AlertCircle } from 'lucide-react';

interface FileUploadProps {
  onFileSelect: (file: File) => void;
  disabled?: boolean;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onFileSelect, disabled }) => {
  const [isDragging, setIsDragging] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const validateFile = (file: File): boolean => {
    if (file.type !== 'application/pdf') {
      setError('Por favor, envie apenas arquivos PDF.');
      return false;
    }
    // Limit to roughly 20MB for browser performance sanity, although Gemini supports more
    if (file.size > 20 * 1024 * 1024) {
      setError('O arquivo é muito grande. O limite é 20MB.');
      return false;
    }
    setError(null);
    return true;
  };

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    if (!disabled) setIsDragging(true);
  }, [disabled]);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (disabled) return;

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const file = e.dataTransfer.files[0];
      if (validateFile(file)) {
        onFileSelect(file);
      }
    }
  }, [onFileSelect, disabled]);

  const handleFileInput = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      if (validateFile(file)) {
        onFileSelect(file);
      }
    }
  }, [onFileSelect]);

  return (
    <div className="w-full max-w-xl mx-auto">
      <div
        className={`
          relative group cursor-pointer
          border-2 border-dashed rounded-2xl p-10 transition-all duration-300 ease-in-out
          flex flex-col items-center justify-center text-center
          ${isDragging 
            ? 'border-brand-500 bg-brand-50 scale-[1.02]' 
            : 'border-slate-300 hover:border-brand-400 hover:bg-slate-50 bg-white'
          }
          ${disabled ? 'opacity-50 cursor-not-allowed grayscale' : ''}
        `}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={() => !disabled && document.getElementById('file-upload')?.click()}
      >
        <input
          id="file-upload"
          type="file"
          accept=".pdf"
          className="hidden"
          onChange={handleFileInput}
          disabled={disabled}
        />

        <div className={`
          p-4 rounded-full mb-4 transition-colors duration-300
          ${isDragging ? 'bg-brand-100 text-brand-600' : 'bg-slate-100 text-slate-500 group-hover:bg-brand-50 group-hover:text-brand-500'}
        `}>
          {isDragging ? <Upload size={32} /> : <FileText size={32} />}
        </div>

        <h3 className="text-lg font-semibold text-slate-700 mb-1">
          {isDragging ? 'Solte o arquivo aqui' : 'Clique ou arraste um PDF'}
        </h3>
        <p className="text-sm text-slate-500 max-w-xs">
          Suporta arquivos PDF locais. O processamento é feito diretamente com a IA.
        </p>
      </div>

      {error && (
        <div className="mt-4 p-3 bg-red-50 border border-red-200 rounded-lg flex items-center gap-2 text-red-600 text-sm animate-fade-in">
          <AlertCircle size={16} />
          <span>{error}</span>
        </div>
      )}
    </div>
  );
};

import React from 'react';
import ReactMarkdown from 'react-markdown';
import { Download, RefreshCcw, FileText } from 'lucide-react';

interface SummaryDisplayProps {
  summary: string;
  fileName: string;
  onReset: () => void;
}

export const SummaryDisplay: React.FC<SummaryDisplayProps> = ({ summary, fileName, onReset }) => {

  const handleDownload = () => {
    const blob = new Blob([summary], { type: 'text/markdown' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `resumo-${fileName.replace('.pdf', '')}.md`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="flex flex-col h-full max-h-full overflow-hidden bg-white rounded-2xl shadow-xl border border-slate-200">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 bg-slate-50">
        <div className="flex items-center gap-3">
            <div className="p-2 bg-white border border-slate-200 rounded-lg text-brand-600">
                <FileText size={20} />
            </div>
            <div>
                <h2 className="text-sm font-semibold text-slate-800">Resumo Gerado</h2>
                <p className="text-xs text-slate-500 truncate max-w-[200px]">{fileName}</p>
            </div>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={onReset}
            className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium text-slate-600 hover:text-brand-600 hover:bg-brand-50 rounded-lg transition-colors"
          >
            <RefreshCcw size={16} />
            <span className="hidden sm:inline">Novo Arquivo</span>
          </button>
          <button
            onClick={handleDownload}
            className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium text-white bg-brand-600 hover:bg-brand-700 rounded-lg shadow-sm transition-colors"
          >
            <Download size={16} />
            <span className="hidden sm:inline">Download .md</span>
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
        <div className="prose prose-slate prose-lg max-w-none prose-headings:text-brand-900 prose-a:text-brand-600">
          <ReactMarkdown>{summary}</ReactMarkdown>
        </div>
      </div>
    </div>
  );
};

