import { GoogleGenAI, SchemaType } from "@google/genai";
import { RpgMetadata } from "../types";

// Ensure API key is available
if (!process.env.API_KEY) {
  console.error("API_KEY is missing from environment variables.");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Sends a PDF base64 string to Gemini and requests structured RPG metadata.
 */
export const analyzeRpgPdf = async (base64Pdf: string, fileName: string): Promise<RpgMetadata> => {
  try {
    // Usando Gemini 1.5 Flash ou 2.0 Flash (usando alias latest para garantir velocidade)
    // O modelo deve suportar JSON Mode nativamente
    const modelId = 'gemini-2.0-flash-exp'; 

    const prompt = `
      Atue como um arquivista especialista em RPG de Mesa (T20, D&D, Tormenta, etc). 
      Analise este documento visualmente e extraia as informações no formato JSON.

      Arquivo original: "${fileName}"

      Regras de extração:
      1. filename_suffix: Um sufixo curto em snake_case para nomear o arquivo (ex: regras_basicas, aventura_iniciante).
      2. summary: Resumo ultra conciso (max 150 caracteres).
      3. system: O sistema de RPG (ex: T20, D&D 5e, 3D&T, Call of Cthulhu). Se não identificar, use "Genérico".
      4. type: Tipo do conteúdo (ex: Livro Básico, Suplemento, Aventura, Ficha, Mapa).
      5. level_recommendation: Níveis recomendados se for aventura (ex: "1-5", "N/A").
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          { inlineData: { mimeType: 'application/pdf', data: base64Pdf } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: SchemaType.OBJECT,
          properties: {
            filename_suffix: { type: SchemaType.STRING },
            summary: { type: SchemaType.STRING },
            system: { type: SchemaType.STRING },
            type: { type: SchemaType.STRING },
            level_recommendation: { type: SchemaType.STRING },
          },
          required: ["filename_suffix", "summary", "system", "type", "level_recommendation"]
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("A resposta da IA estava vazia.");
    }

    // Parse JSON response
    const data = JSON.parse(text) as RpgMetadata;
    return data;

  } catch (error: any) {
    console.error("Gemini API Error:", error);
    let errorMessage = "Erro ao analisar.";

    if (error.message) {
      if (error.message.includes("429")) {
        errorMessage = "Rate Limit (429). Aguardando...";
      } else if (error.message.includes("404")) {
        errorMessage = "Modelo indisponível.";
      }
    }
    throw new Error(errorMessage);
  }
};

import React, { useCallback, useState } from 'react';
import { Upload, FileText, AlertCircle, Layers } from 'lucide-react';

interface FileUploadProps {
  onFilesSelect: (files: File[]) => void;
  disabled?: boolean;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onFilesSelect, disabled }) => {
  const [isDragging, setIsDragging] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const validateFiles = (fileList: FileList | File[]): File[] => {
    const validFiles: File[] = [];
    let hasInvalidType = false;

    Array.from(fileList).forEach(file => {
      if (file.type === 'application/pdf') {
        validFiles.push(file);
      } else {
        hasInvalidType = true;
      }
    });

    if (hasInvalidType) {
      setError('Alguns arquivos foram ignorados pois não são PDFs.');
    } else {
      setError(null);
    }

    return validFiles;
  };

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    if (!disabled) setIsDragging(true);
  }, [disabled]);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (disabled) return;

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const validFiles = validateFiles(e.dataTransfer.files);
      if (validFiles.length > 0) {
        onFilesSelect(validFiles);
      }
    }
  }, [onFilesSelect, disabled]);

  const handleFileInput = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const validFiles = validateFiles(e.target.files);
      if (validFiles.length > 0) {
        onFilesSelect(validFiles);
      }
    }
  }, [onFilesSelect]);

  return (
    <div className="w-full max-w-xl mx-auto">
      <div
        className={`
          relative group cursor-pointer
          border-2 border-dashed rounded-2xl p-10 transition-all duration-300 ease-in-out
          flex flex-col items-center justify-center text-center
          ${isDragging 
            ? 'border-brand-500 bg-brand-50 scale-[1.02]' 
            : 'border-slate-300 hover:border-brand-400 hover:bg-slate-50 bg-white'
          }
          ${disabled ? 'opacity-50 cursor-not-allowed grayscale' : ''}
        `}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={() => !disabled && document.getElementById('file-upload')?.click()}
      >
        <input
          id="file-upload"
          type="file"
          accept=".pdf"
          multiple
          className="hidden"
          onChange={handleFileInput}
          disabled={disabled}
        />

        <div className={`
          p-4 rounded-full mb-4 transition-colors duration-300
          ${isDragging ? 'bg-brand-100 text-brand-600' : 'bg-slate-100 text-slate-500 group-hover:bg-brand-50 group-hover:text-brand-500'}
        `}>
          {isDragging ? <Layers size={32} /> : <FileText size={32} />}
        </div>

        <h3 className="text-lg font-semibold text-slate-700 mb-1">
          {isDragging ? 'Solte os arquivos aqui' : 'Clique ou arraste seus PDFs'}
        </h3>
        <p className="text-sm text-slate-500 max-w-xs leading-relaxed">
          Arraste múltiplos arquivos ou uma pasta inteira para indexar sua biblioteca de RPG.
        </p>
      </div>

      {error && (
        <div className="mt-4 p-3 bg-red-50 border border-red-200 rounded-lg flex items-center gap-2 text-red-600 text-sm animate-fade-in">
          <AlertCircle size={16} />
          <span>{error}</span>
