  // Calculate Metrics
  const metrics = useMemo(() => {
    const doneItems = library.filter(i => i.status === 'done' && i.metadata);
    const systems = new Set(doneItems.map(i => i.metadata?.system));
    const adventures = doneItems.filter(i => i.metadata?.type?.toLowerCase().includes('aventura'));

    return {
      total: doneItems.length,
      systems: systems.size,
      adventures: adventures.length
    };
  }, [library]);

  // Derived Lists for Select Inputs
  const availableSystems = useMemo(() => {
    const systems = new Set(library.map(i => i.metadata?.system).filter(Boolean));
    return ["Todos", ...Array.from(systems).sort()];
  }, [library]);

  const availableTypes = useMemo(() => {
    const types = new Set(library.map(i => i.metadata?.type).filter(Boolean));
    return ["Todos", ...Array.from(types).sort()];
  }, [library]);

  // Filtering Logic
  const filteredLibrary = useMemo(() => {
    return library.filter(item => {
      if (item.status !== 'done' || !item.metadata) return false;

      const matchesSystem = filters.system === "Todos" || item.metadata.system === filters.system;
      const matchesType = filters.type === "Todos" || item.metadata.type === filters.type;
      const searchLower = filters.search.toLowerCase();
      const matchesSearch = !filters.search || 
        item.suggestedName.toLowerCase().includes(searchLower) ||
        item.metadata.summary.toLowerCase().includes(searchLower);

      return matchesSystem && matchesType && matchesSearch;
    });
  }, [library, filters]);

  return (
