        ) : (
          <Dashboard 
            library={library} 
            filters={filters} 
            setFilters={setFilters} 
          />
        )}

      </main>

      {/* Floating Action Button for Adding More */}
      {appState === AppState.DASHBOARD && (
        <div className="fixed bottom-8 right-8 z-40">
           <label 
             htmlFor="fab-upload"
             className="flex items-center gap-2 bg-brand-600 hover:bg-brand-700 text-white px-6 py-4 rounded-full shadow-lg cursor-pointer transition-transform hover:scale-105 active:scale-95"
           >
             <Plus size={24} />
