  type: string;
  search: string;
}

import { LibraryEntry, FileSystemDirectoryHandle, FileSystemFileHandle } from '../types';

/**
 * Recursively reads files from a directory handle.
 */
export async function getFilesRecursively(
  dirHandle: FileSystemDirectoryHandle, 
  path = ''
): Promise<LibraryEntry[]> {
  const entries: LibraryEntry[] = [];

  // @ts-ignore - TS definition for async iterator on handles might be missing in strict mode
  for await (const entry of dirHandle.values()) {
    if (entry.kind === 'file') {
      const fileHandle = entry as FileSystemFileHandle;
      if (fileHandle.name.toLowerCase().endsWith('.pdf')) {
        const file = await fileHandle.getFile();

        entries.push({
          id: crypto.randomUUID(),
          handle: fileHandle,
          file: file,
          originalName: file.name,
          relativePath: path + file.name,
          suggestedName: 'Aguardando análise...',
          metadata: null,
          status: 'pending',
          timestamp: new Date().toISOString()
        });
      }
    } else if (entry.kind === 'directory') {
      const newPath = `${path}${entry.name}/`;
      const subEntries = await getFilesRecursively(entry as FileSystemDirectoryHandle, newPath);
      entries.push(...subEntries);
    }
  }

  return entries;
}

/**
 * Renames a file on the user's disk using the File System Access API.
 */
export async function renameFileOnDisk(entry: LibraryEntry): Promise<void> {
  if (!entry.handle || !entry.suggestedName) {
    throw new Error("Handle de arquivo inválido ou nome sugerido ausente.");
  }

  // The 'move' method is currently the way to rename in Chromium
  // It effectively renames the file in place.
  if (entry.handle.move) {
    await entry.handle.move(entry.suggestedName);
  } else {
    throw new Error("Seu navegador não suporta renomeação automática de arquivos (Feature: FileSystemHandle.move). Use o Chrome ou Edge.");
  }
}

import React, { useState } from 'react';
import { FolderOpen, AlertCircle, HardDrive } from 'lucide-react';
import { LibraryEntry } from '../types';
import { getFilesRecursively } from '../utils/fileSystem';

interface FileUploadProps {
  onEntriesLoaded: (entries: LibraryEntry[]) => void;
  disabled?: boolean;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onEntriesLoaded, disabled }) => {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleDirectoryPick = async () => {
    setError(null);
    setIsLoading(true);

    try {
      // @ts-ignore - Window interface extension
      if (!window.showDirectoryPicker) {
        throw new Error("Seu navegador não suporta leitura de pastas. Por favor, use Google Chrome, Edge ou Opera Desktop.");
      }

      // @ts-ignore
      const dirHandle = await window.showDirectoryPicker({
        id: 'rpg-library',
        mode: 'readwrite' // Request write permission immediately for future renaming
      });

      const entries = await getFilesRecursively(dirHandle);

      if (entries.length === 0) {
        setError("Nenhum arquivo PDF encontrado nesta pasta ou subpastas.");
      } else {
        onEntriesLoaded(entries);
      }

    } catch (err: any) {
      if (err.name === 'AbortError') {
        // User cancelled, do nothing
        return;
      }
      console.error(err);
      setError(err.message || "Erro ao ler diretório.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="w-full max-w-xl mx-auto">
      <div
        onClick={!disabled && !isLoading ? handleDirectoryPick : undefined}
        className={`
          relative group cursor-pointer
          border-2 border-dashed rounded-2xl p-10 transition-all duration-300 ease-in-out
          flex flex-col items-center justify-center text-center
          ${isLoading
            ? 'border-brand-300 bg-brand-50 cursor-wait'
            : 'border-slate-300 hover:border-brand-400 hover:bg-slate-50 bg-white'
          }
          ${disabled ? 'opacity-50 cursor-not-allowed grayscale' : ''}
        `}
      >
        <div className={`
          p-4 rounded-full mb-4 transition-colors duration-300
          ${isLoading ? 'bg-brand-100 animate-pulse text-brand-600' : 'bg-slate-100 text-slate-500 group-hover:bg-brand-50 group-hover:text-brand-500'}
        `}>
          {isLoading ? <HardDrive size={32} /> : <FolderOpen size={32} />}
        </div>

        <h3 className="text-lg font-semibold text-slate-700 mb-1">
          {isLoading ? 'Lendo pastas...' : 'Selecionar Pasta Raiz'}
        </h3>
        <p className="text-sm text-slate-500 max-w-xs leading-relaxed">
          Clique para selecionar a pasta onde estão seus PDFs. <br/>
          <span className="font-semibold text-brand-600">Lê recursivamente todas as subpastas.</span>
        </p>
      </div>

      {error && (
        <div className="mt-4 p-3 bg-red-50 border border-red-200 rounded-lg flex items-center gap-2 text-red-600 text-sm animate-fade-in">
          <AlertCircle size={16} />
          <span>{error}</span>
        </div>
      )}

      <div className="mt-6 text-center">
        <p className="text-xs text-slate-400">
           Nota: Requer permissão de edição para renomear os arquivos automaticamente.
        </p>
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { LibraryEntry, FilterState } from '../types';
import { Search, Filter, BookOpen, Sword, Scroll, Download, CheckCircle, Save, FolderInput } from 'lucide-react';

interface DashboardProps {
  library: LibraryEntry[];
  filters: FilterState;
  setFilters: React.Dispatch<React.SetStateAction<FilterState>>;
  onRenameClick: () => void;
  isRenaming: boolean;
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  library, filters, setFilters, onRenameClick, isRenaming 
}) => {

  // Calculate Metrics
  const metrics = useMemo(() => {
    const doneItems = library.filter(i => (i.status === 'done' || i.status === 'renamed') && i.metadata);
    const systems = new Set(doneItems.map(i => i.metadata?.system));
    const adventures = doneItems.filter(i => i.metadata?.type?.toLowerCase().includes('aventura'));
    const renamed = library.filter(i => i.status === 'renamed').length;

    return {
      total: doneItems.length,
      systems: systems.size,
      adventures: adventures.length,
      renamed
    };
  }, [library]);

  const availableSystems = useMemo(() => {
    const systems = new Set(library.map(i => i.metadata?.system).filter(Boolean));
    return ["Todos", ...Array.from(systems).sort()];
  }, [library]);

  const availableTypes = useMemo(() => {
    const types = new Set(library.map(i => i.metadata?.type).filter(Boolean));
    return ["Todos", ...Array.from(types).sort()];
  }, [library]);

  const filteredLibrary = useMemo(() => {
    return library.filter(item => {
      // Show items that are done, renamed, or even analyzing if user wants to see progress in list
      if (!['done', 'renamed'].includes(item.status) || !item.metadata) return false;

      const matchesSystem = filters.system === "Todos" || item.metadata.system === filters.system;
      const matchesType = filters.type === "Todos" || item.metadata.type === filters.type;
      const searchLower = filters.search.toLowerCase();
      const matchesSearch = !filters.search || 
        item.suggestedName.toLowerCase().includes(searchLower) ||
        item.metadata.summary.toLowerCase().includes(searchLower);

      return matchesSystem && matchesType && matchesSearch;
    });
  }, [library, filters]);

  const handleExport = () => {
    const dataStr = JSON.stringify(library.map(l => ({
        original: l.originalName,
        new: l.suggestedName,
        path: l.relativePath,
        metadata: l.metadata,
        processed_at: l.timestamp
    })), null, 2);

    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `rpg_library_manifest_${new Date().toISOString().slice(0,10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  const pendingRenames = library.filter(i => i.status === 'done').length;

  return (
    <div className="flex flex-col h-full gap-6">

      {/* Header Actions */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Acervo Digital</h2>
          <p className="text-sm text-slate-500">Gerencie, filtre e exporte sua biblioteca.</p>
