import React, { useState, useCallback, useEffect } from 'react';
import { BrainCircuit, Sparkles, Loader2, Plus, HardDrive } from 'lucide-react';
import { AppState, LibraryEntry, FilterState } from './types';
import { fileToBase64 } from './utils/fileUtils';
import { renameFileOnDisk } from './utils/fileSystem';
import { analyzeRpgPdf } from './services/geminiService';
import { FileUpload } from './components/FileUpload';
import { Dashboard } from './components/Dashboard';

const App: React.FC = () => {
  const [library, setLibrary] = useState<LibraryEntry[]>([]);
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [isRenaming, setIsRenaming] = useState(false);

  const [filters, setFilters] = useState<FilterState>({
    system: 'Todos',
    type: 'Todos',
    search: ''
  });

  // --- File Processing Logic (AI Analysis) ---
  const processFile = useCallback(async (entry: LibraryEntry) => {
    try {
      const base64 = await fileToBase64(entry.file);
      const metadata = await analyzeRpgPdf(base64, entry.originalName);

      // Generate suggested filename logic
      const editionMatch = entry.originalName.match(/(\d+)/);
      const edition = editionMatch ? editionMatch[1] : "00";

      // Extract a simple folder tag from relative path if possible (e.g., "DnD5e/Books/File.pdf" -> "DnD5e")
      const pathParts = entry.relativePath.split('/');
      const folderTag = pathParts.length > 1 ? pathParts[0].substring(0,6).replace(/[^a-zA-Z0-9]/g, '').toUpperCase() : "ROOT";

      const suffix = metadata.filename_suffix.replace(/[^a-zA-Z0-9_]/g, '_').substring(0, 50);
      const newName = `DB_${edition}_${folderTag}_${suffix}.pdf`;

      setLibrary(prev => prev.map(item => 
        item.id === entry.id 
          ? { ...item, status: 'done', metadata, suggestedName: newName } 
          : item
      ));

    } catch (error: any) {
      console.error(`Error processing ${entry.originalName}:`, error);
      setLibrary(prev => prev.map(item => 
        item.id === entry.id 
          ? { ...item, status: 'error', error: error.message } 
          : item
      ));
    } finally {
      setProcessingQueue(prev => prev.filter(id => id !== entry.id));
    }
  }, []);

  // --- Queue Management ---
  useEffect(() => {
    const nextItem = library.find(item => item.status === 'pending' && !processingQueue.includes(item.id));

    // Process 1 at a time to be safe with Rate Limits and Browser Memory
    if (nextItem && processingQueue.length < 1) { 
      setProcessingQueue(prev => [...prev, nextItem.id]);
      setLibrary(prev => prev.map(i => i.id === nextItem.id ? { ...i, status: 'analyzing' } : i));
      processFile(nextItem);
    }
  }, [library, processingQueue, processFile]);

  // --- Batch Renaming Logic ---
  const handleRenameBatch = async () => {
    if (!window.confirm("Isso renomeará os arquivos no seu disco permanentemente. Deseja continuar?")) return;

    setIsRenaming(true);
    const toRename = library.filter(i => i.status === 'done' && i.suggestedName !== i.originalName);

    for (const item of toRename) {
      try {
        await renameFileOnDisk(item);
        setLibrary(prev => prev.map(i => i.id === item.id ? { ...i, status: 'renamed' } : i));
      } catch (e: any) {
        console.error(`Falha ao renomear ${item.originalName}:`, e);
        // Optional: Update status to error or specific rename-error status
      }
    }
    setIsRenaming(false);
  };

  const handleEntriesLoaded = (entries: LibraryEntry[]) => {
    setLibrary(prev => [...prev, ...entries]);
    setAppState(AppState.DASHBOARD);
  };

  // --- Render Helpers ---

  const processingCount = library.filter(i => i.status === 'pending' || i.status === 'analyzing').length;
  const progressPercent = library.length > 0 
    ? ((library.length - processingCount) / library.length) * 100 
    : 0;

  return (
    <div className="flex flex-col h-screen bg-slate-50">

      {/* Header */}
      <nav className="w-full px-6 py-3 flex items-center justify-between border-b border-slate-200 bg-white z-50 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="bg-brand-600 p-2 rounded-lg">
            <BrainCircuit className="text-white w-6 h-6" />
          </div>
          <div className="flex flex-col">
            <span className="text-lg font-bold text-slate-800 leading-tight">
              T20 RPG Indexer
            </span>
            <span className="text-xs text-slate-500">Local File System Edition</span>
          </div>
        </div>

        {/* Global Status Indicator */}
        <div className="flex items-center gap-4">
           {processingCount > 0 && (
             <div className="flex items-center gap-3 bg-brand-50 px-3 py-1.5 rounded-full border border-brand-100">
               <Loader2 className="w-4 h-4 text-brand-600 animate-spin" />
               <div className="flex flex-col min-w-[120px]">
                 <span className="text-xs font-semibold text-brand-700">Indexando... {library.length - processingCount}/{library.length}</span>
                 <div className="w-full bg-brand-200 rounded-full h-1 mt-1">
                   <div className="bg-brand-500 h-1 rounded-full transition-all duration-300" style={{ width: `${progressPercent}%` }}></div>
                 </div>
               </div>
             </div>
           )}
           <div className="hidden sm:flex items-center gap-2 text-xs text-slate-500 bg-slate-100 px-3 py-1 rounded-md">
            <Sparkles size={12} className="text-brand-500" />
            <span>Gemini 2.0 Flash</span>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden p-6 max-w-[1600px] w-full mx-auto">

        {appState === AppState.IDLE ? (
          <div className="h-full flex flex-col items-center justify-center animate-fade-in-up">
            <div className="text-center space-y-6 max-w-2xl">
              <h1 className="text-4xl font-extrabold text-slate-900">
                Organize seu acervo local <br/>
                <span className="text-brand-600">direto no navegador.</span>
              </h1>
              <p className="text-lg text-slate-600">
                Selecione uma pasta raiz. A IA analisará recursivamente, gerará metadados e renomeará seus arquivos para manter tudo organizado.
              </p>

              <div className="bg-yellow-50 border border-yellow-200 p-4 rounded-lg text-sm text-yellow-800 text-left mx-auto max-w-lg">
                <strong>Nota Importante:</strong> Esta versão utiliza a <em>File System Access API</em>. 
                Ela requer um navegador compatível (Chrome, Edge, Opera Desktop) para ler pastas e renomear arquivos no disco.
              </div>

              <div className="pt-4 w-full max-w-xl mx-auto">
                <FileUpload onEntriesLoaded={handleEntriesLoaded} />
              </div>
            </div>
          </div>
        ) : (
          <Dashboard 
            library={library} 
            filters={filters} 
            setFilters={setFilters} 
            onRenameClick={handleRenameBatch}
            isRenaming={isRenaming}
          />
        )}

      </main>
    </div>
  );
};

export default App;

import { LibraryEntry, FileSystemDirectoryHandle, FileSystemFileHandle } from '../types';

/**
 * Recursively reads files from a directory handle.
 */
export async function getFilesRecursively(
  dirHandle: FileSystemDirectoryHandle, 
  path = ''
): Promise<LibraryEntry[]> {
  const entries: LibraryEntry[] = [];

  // @ts-ignore - TS definition for async iterator on handles might be missing in strict mode
  for await (const entry of dirHandle.values()) {
    if (entry.kind === 'file') {
      const fileHandle = entry as FileSystemFileHandle;
      if (fileHandle.name.toLowerCase().endsWith('.pdf')) {
        const file = await fileHandle.getFile();

        entries.push({
          id: crypto.randomUUID(),
          handle: fileHandle,
          file: file,
          originalName: file.name,
          relativePath: path + file.name,
          suggestedName: 'Aguardando análise...',
          metadata: null,
          status: 'pending',
          timestamp: new Date().toISOString()
        });
      }
    } else if (entry.kind === 'directory') {
      const newPath = `${path}${entry.name}/`;
      const subEntries = await getFilesRecursively(entry as FileSystemDirectoryHandle, newPath);
      entries.push(...subEntries);
    }
  }

  return entries;
}

/**
 * Converts a standard FileList (from input fallback) to LibraryEntry objects.
 * Note: Handles will be null, so direct disk renaming won't be possible.
 */
export function processFileList(fileList: FileList): LibraryEntry[] {
  const entries: LibraryEntry[] = [];
  Array.from(fileList).forEach(file => {
    if (file.name.toLowerCase().endsWith('.pdf')) {
      entries.push({
        id: crypto.randomUUID(),
        handle: null, // Fallback mode has no direct disk handle
        file: file,
        originalName: file.name,
        // webkitRelativePath is standard for directory inputs
        relativePath: file.webkitRelativePath || file.name, 
        suggestedName: 'Aguardando análise...',
        metadata: null,
        status: 'pending',
        timestamp: new Date().toISOString()
      });
    }
  });
  return entries;
}

/**
 * Renames a file on the user's disk using the File System Access API.
 */
export async function renameFileOnDisk(entry: LibraryEntry): Promise<void> {
  if (!entry.handle) {
    throw new Error("Modo de compatibilidade: O acesso direto ao disco não está disponível. Execute fora de iframes/sandboxes para usar esta função.");
  }

  if (!entry.suggestedName) {
    throw new Error("Nome sugerido ausente.");
  }

  // The 'move' method is currently the way to rename in Chromium
  // It effectively renames the file in place.
  if (entry.handle.move) {
    await entry.handle.move(entry.suggestedName);
  } else {
    throw new Error("Seu navegador não suporta renomeação automática de arquivos (Feature: FileSystemHandle.move). Use o Chrome ou Edge.");
  }
}

import React, { useState, useRef } from 'react';
import { FolderOpen, AlertCircle, HardDrive } from 'lucide-react';
import { LibraryEntry } from '../types';
import { getFilesRecursively, processFileList } from '../utils/fileSystem';

interface FileUploadProps {
  onEntriesLoaded: (entries: LibraryEntry[]) => void;
  disabled?: boolean;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onEntriesLoaded, disabled }) => {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Ref for the fallback input element
  const inputRef = useRef<HTMLInputElement>(null);

  const handleDirectoryPick = async () => {
    setError(null);
    setIsLoading(true);

    try {
      // Check if API exists
      // @ts-ignore
      if (typeof window.showDirectoryPicker === 'function') {
         try {
            // @ts-ignore
            const dirHandle = await window.showDirectoryPicker({
              id: 'rpg-library',
              mode: 'readwrite' 
            });

            const entries = await getFilesRecursively(dirHandle);

            if (entries.length === 0) {
              throw new Error("Nenhum arquivo PDF encontrado nesta pasta ou subpastas.");
            } else {
              onEntriesLoaded(entries);
              setIsLoading(false);
              return; // Success with Native API
            }
         } catch (nativeErr: any) {
            // If user simply cancelled, stop
            if (nativeErr.name === 'AbortError') {
              setIsLoading(false);
              return;
            }

            // If it's a security error (iframe) or not supported, log and fall through to input click
            console.warn("Native File System API failed (likely iframe restriction), falling back to input:", nativeErr);
         }
      }

      // FALLBACK: Trigger hidden input click
      // This works even in iframes where showDirectoryPicker is blocked
      if (inputRef.current) {
        inputRef.current.click();
      } else {
        throw new Error("Input de arquivo não disponível.");
      }

    } catch (err: any) {
      console.error(err);
      setError(err.message || "Erro ao ler diretório.");
      setIsLoading(false);
    }
  };

  const handleInputFiles = (e: React.ChangeEvent<HTMLInputElement>) => {
    setIsLoading(true);
    if (e.target.files && e.target.files.length > 0) {
      const entries = processFileList(e.target.files);
      if (entries.length === 0) {
        setError("Nenhum arquivo PDF encontrado.");
      } else {
        onEntriesLoaded(entries);
      }
    }
    setIsLoading(false);
    // Reset value to allow selecting same folder again if needed
    e.target.value = '';
  };

  return (
    <div className="w-full max-w-xl mx-auto">
      {/* Hidden Fallback Input */}
      <input
        ref={inputRef}
        type="file"
        accept=".pdf"
        multiple
        className="hidden"
        onChange={handleInputFiles}
        // @ts-ignore - React doesn't support webkitdirectory typing yet
        webkitdirectory=""
        directory="" 
      />

      <div
        onClick={!disabled && !isLoading ? handleDirectoryPick : undefined}
        className={`
          relative group cursor-pointer
          border-2 border-dashed rounded-2xl p-10 transition-all duration-300 ease-in-out
          flex flex-col items-center justify-center text-center
          ${isLoading
            ? 'border-brand-300 bg-brand-50 cursor-wait'
            : 'border-slate-300 hover:border-brand-400 hover:bg-slate-50 bg-white'
          }
          ${disabled ? 'opacity-50 cursor-not-allowed grayscale' : ''}
        `}
      >
        <div className={`
          p-4 rounded-full mb-4 transition-colors duration-300
          ${isLoading ? 'bg-brand-100 animate-pulse text-brand-600' : 'bg-slate-100 text-slate-500 group-hover:bg-brand-50 group-hover:text-brand-500'}
        `}>
          {isLoading ? <HardDrive size={32} /> : <FolderOpen size={32} />}
        </div>

        <h3 className="text-lg font-semibold text-slate-700 mb-1">
          {isLoading ? 'Lendo pastas...' : 'Selecionar Pasta Raiz'}
        </h3>
        <p className="text-sm text-slate-500 max-w-xs leading-relaxed">
          Clique para selecionar a pasta onde estão seus PDFs. <br/>
          <span className="font-semibold text-brand-600">Lê recursivamente todas as subpastas.</span>
        </p>
      </div>

      {error && (
        <div className="mt-4 p-3 bg-red-50 border border-red-200 rounded-lg flex items-center gap-2 text-red-600 text-sm animate-fade-in">
          <AlertCircle size={16} />
          <span>{error}</span>
        </div>
      )}

      <div className="mt-6 text-center">
        <p className="text-xs text-slate-400">
           Nota: A renomeação automática requer suporte a File System API (Chrome/Edge Desktop).
        </p>
      </div>
    </div>
  );
};

