              <div className="bg-yellow-50 border border-yellow-200 p-4 rounded-lg text-sm text-yellow-800 text-left mx-auto max-w-lg">
                <strong>Nota Importante:</strong> A renomeação automática de arquivos requer um navegador compatível com a API de Sistema de Arquivos (Chrome/Edge em Desktop). Em outros ambientes, o modo de leitura será ativado.
              </div>

              <div className="pt-4 w-full max-w-xl mx-auto">
                <FileUpload onEntriesLoaded={handleEntriesLoaded} />
              </div>
            </div>
          </div>
        ) : (
          <Dashboard 
            library={library} 
            filters={filters} 
            setFilters={setFilters} 
            onRenameClick={handleRenameBatch}
            isRenaming={isRenaming}
          />
        )}

      </main>
    </div>
  );
};

export default App;

export enum AppState {
  IDLE = 'IDLE',
  PROCESSING = 'PROCESSING',
  DASHBOARD = 'DASHBOARD',
  ERROR = 'ERROR'
}

export interface RpgMetadata {
  filename_suffix: string;
  summary: string;
  system: string;
  type: string;
  level_recommendation: string;
}

// Interface for Native File System Handle
export interface FileSystemFileHandle extends FileSystemHandle {
  getFile: () => Promise<File>;
  move: (newName: string) => Promise<void>;
}

export interface FileSystemDirectoryHandle extends FileSystemHandle {
  values: () => AsyncIterableIterator<FileSystemHandle>;
  getDirectoryHandle: (name: string) => Promise<FileSystemDirectoryHandle>;
  getFileHandle: (name: string) => Promise<FileSystemFileHandle>;
}

export interface LibraryEntry {
  id: string;
  handle: FileSystemFileHandle | null; // The link to the real file on disk
  file: File;
  originalName: string;
  relativePath: string; // Folder structure path
  suggestedName: string;
  metadata: RpgMetadata | null;
  status: 'pending' | 'analyzing' | 'done' | 'renamed' | 'error';
  error?: string;
  timestamp: string;
}

export interface ExportedEntry {
  original: string;
  new: string;
  path: string; // original relative path
  metadata: RpgMetadata | null;
  status: string;
  processed_at: string;
}

export interface FilterState {
  system: string;
  type: string;
  search: string;
}

import React, { useMemo } from 'react';
import { LibraryEntry, FilterState } from '../types';
import { Search, Filter, BookOpen, Sword, Scroll, Download, CheckCircle, Save, FolderInput } from 'lucide-react';

interface DashboardProps {
  library: LibraryEntry[];
  filters: FilterState;
  setFilters: React.Dispatch<React.SetStateAction<FilterState>>;
  onRenameClick: () => void;
  isRenaming: boolean;
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  library, filters, setFilters, onRenameClick, isRenaming 
}) => {

  // Calculate Metrics
  const metrics = useMemo(() => {
    const doneItems = library.filter(i => (i.status === 'done' || i.status === 'renamed') && i.metadata);
    const systems = new Set(doneItems.map(i => i.metadata?.system));
    const adventures = doneItems.filter(i => i.metadata?.type?.toLowerCase().includes('aventura'));
    const renamed = library.filter(i => i.status === 'renamed').length;

    return {
      total: doneItems.length,
      systems: systems.size,
      adventures: adventures.length,
      renamed
    };
  }, [library]);

  const availableSystems = useMemo(() => {
    const systems = new Set(library.map(i => i.metadata?.system).filter(Boolean));
    return ["Todos", ...Array.from(systems).sort()];
  }, [library]);

  const availableTypes = useMemo(() => {
    const types = new Set(library.map(i => i.metadata?.type).filter(Boolean));
    return ["Todos", ...Array.from(types).sort()];
  }, [library]);

  const filteredLibrary = useMemo(() => {
    return library.filter(item => {
      // Show items that are done, renamed, or even analyzing if user wants to see progress in list
      if (!['done', 'renamed'].includes(item.status) || !item.metadata) return false;

      const matchesSystem = filters.system === "Todos" || item.metadata.system === filters.system;
      const matchesType = filters.type === "Todos" || item.metadata.type === filters.type;
      const searchLower = filters.search.toLowerCase();
      const matchesSearch = !filters.search || 
        item.suggestedName.toLowerCase().includes(searchLower) ||
        item.metadata.summary.toLowerCase().includes(searchLower);

      return matchesSystem && matchesType && matchesSearch;
    });
  }, [library, filters]);

  const handleExport = () => {
    const dataStr = JSON.stringify(library.map(l => ({
        original: l.originalName,
        new: l.suggestedName,
        path: l.relativePath,
        metadata: l.metadata,
        status: l.status,
        processed_at: l.timestamp
    })), null, 2);

    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `rpg_library_manifest_${new Date().toISOString().slice(0,10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  const pendingRenames = library.filter(i => i.status === 'done').length;

  return (
    <div className="flex flex-col h-full gap-6">

      {/* Header Actions */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Acervo Digital</h2>
          <p className="text-sm text-slate-500">Gerencie, filtre e exporte sua biblioteca.</p>
        </div>
        <div className="flex gap-3">
             <button
              onClick={handleExport}
              className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 shadow-sm transition-all"
            >
              <Download size={18} />
              <span>Exportar JSON</span>
            </button>

            <button
              onClick={onRenameClick}
              disabled={pendingRenames === 0 || isRenaming}
              className={`
                flex items-center gap-2 px-4 py-2 rounded-lg shadow-sm text-white transition-all
                ${pendingRenames > 0 && !isRenaming ? 'bg-brand-600 hover:bg-brand-700' : 'bg-slate-300 cursor-not-allowed'}
              `}
            >
              {isRenaming ? <FolderInput size={18} className="animate-spin" /> : <Save size={18} />}
              <span>{isRenaming ? 'Renomeando...' : `Aplicar Renomeação (${pendingRenames})`}</span>
            </button>
        </div>
      </div>

      {/* Metrics Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
            <p className="text-xs text-slate-500 font-medium uppercase">Arquivos</p>
            <div className="flex items-center gap-2 mt-1">
                <BookOpen size={20} className="text-blue-500" />
                <span className="text-2xl font-bold text-slate-800">{metrics.total}</span>
            </div>
        </div>
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
            <p className="text-xs text-slate-500 font-medium uppercase">Sistemas</p>
            <div className="flex items-center gap-2 mt-1">
                <Scroll size={20} className="text-purple-500" />
                <span className="text-2xl font-bold text-slate-800">{metrics.systems}</span>
            </div>
        </div>
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
            <p className="text-xs text-slate-500 font-medium uppercase">Aventuras</p>
            <div className="flex items-center gap-2 mt-1">
                <Sword size={20} className="text-orange-500" />
                <span className="text-2xl font-bold text-slate-800">{metrics.adventures}</span>
            </div>
        </div>
         <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
            <p className="text-xs text-slate-500 font-medium uppercase">Renomeados</p>
            <div className="flex items-center gap-2 mt-1">
                <CheckCircle size={20} className="text-green-500" />
                <span className="text-2xl font-bold text-slate-800">{metrics.renamed}</span>
            </div>
        </div>
      </div>

      {/* Filters Toolbar */}
      <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-4 items-center">
        <div className="flex items-center gap-2 text-slate-500">
          <Filter size={18} />
          <span className="font-medium text-sm">Filtros:</span>
        </div>

        <select 
          className="bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-lg focus:ring-brand-500 focus:border-brand-500 block w-full md:w-40 p-2.5"
          value={filters.system}
          onChange={(e) => setFilters(prev => ({ ...prev, system: e.target.value }))}
        >
          {availableSystems.map(s => <option key={s} value={s}>{s}</option>)}
        </select>

        <select 
          className="bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-lg focus:ring-brand-500 focus:border-brand-500 block w-full md:w-40 p-2.5"
          value={filters.type}
          onChange={(e) => setFilters(prev => ({ ...prev, type: e.target.value }))}
        >
          {availableTypes.map(t => <option key={t} value={t}>{t}</option>)}
        </select>

        <div className="flex-1 w-full relative">
          <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
            <Search size={18} className="text-slate-400" />
          </div>
          <input 
            type="text" 
            className="bg-slate-50 border border-slate-200 text-slate-900 text-sm rounded-lg focus:ring-brand-500 focus:border-brand-500 block w-full pl-10 p-2.5" 
            placeholder="Buscar por nome, resumo ou caminho..."
            value={filters.search}
            onChange={(e) => setFilters(prev => ({ ...prev, search: e.target.value }))}
          />
        </div>
      </div>

      {/* Data Table */}
      <div className="flex-1 bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar flex-1">
          <table className="w-full text-sm text-left text-slate-600">
            <thead className="text-xs text-slate-700 uppercase bg-slate-50 border-b border-slate-200 sticky top-0">
              <tr>
                <th scope="col" className="px-6 py-3 min-w-[250px]">Arquivo (Novo vs Original)</th>
                <th scope="col" className="px-6 py-3">Status</th>
                <th scope="col" className="px-6 py-3">Sistema</th>
                <th scope="col" className="px-6 py-3">Tipo</th>
                <th scope="col" className="px-6 py-3 min-w-[300px]">Resumo</th>
              </tr>
            </thead>
            <tbody>
              {filteredLibrary.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-8 text-center text-slate-400">
                    Nenhum arquivo processado encontrado.
                  </td>
                </tr>
              ) : (
                filteredLibrary.map((item) => (
                  <tr key={item.id} className="bg-white border-b border-slate-100 hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 font-medium text-slate-900">
                      <div className="flex flex-col gap-1">
                        <span className="font-semibold text-brand-700">{item.suggestedName}</span>
                        <span className="text-xs text-slate-400 font-normal flex items-center gap-1">
                             <FolderInput size={10} /> {item.relativePath}
                        </span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      {item.status === 'renamed' ? (
                          <span className="bg-green-100 text-green-800 text-xs font-medium px-2.5 py-0.5 rounded border border-green-200 flex w-fit items-center gap-1">
                              <CheckCircle size={10} /> Renomeado
                          </span>
                      ) : (
                          <span className="bg-yellow-100 text-yellow-800 text-xs font-medium px-2.5 py-0.5 rounded border border-yellow-200">
                              Pendente
                          </span>
                      )}
                    </td>
                    <td className="px-6 py-4">
                      <span className="bg-blue-100 text-blue-800 text-xs font-medium px-2.5 py-0.5 rounded border border-blue-200">
                        {item.metadata?.system}
                      </span>
                    </td>
                    <td className="px-6 py-4">{item.metadata?.type}</td>
                    <td className="px-6 py-4">
                      <p className="line-clamp-2 text-xs leading-relaxed" title={item.metadata?.summary}>
                        {item.metadata?.summary}
                      </p>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

    </div>
  );
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { BrainCircuit, Sparkles, Loader2, Plus, HardDrive, Upload, RefreshCw } from 'lucide-react';
import { AppState, LibraryEntry, FilterState, ExportedEntry } from './types';
import { fileToBase64 } from './utils/fileUtils';
import { renameFileOnDisk } from './utils/fileSystem';
import { analyzeRpgPdf } from './services/geminiService';
import { FileUpload } from './components/FileUpload';
import { Dashboard } from './components/Dashboard';

const App: React.FC = () => {
  const [library, setLibrary] = useState<LibraryEntry[]>([]);
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [isRenaming, setIsRenaming] = useState(false);

  // State for Resume/Import feature
  const [resumeData, setResumeData] = useState<ExportedEntry[] | null>(null);
  const importInputRef = useRef<HTMLInputElement>(null);

  const [filters, setFilters] = useState<FilterState>({
    system: 'Todos',
    type: 'Todos',
    search: ''
  });

  // --- File Processing Logic (AI Analysis) ---
  const processFile = useCallback(async (entry: LibraryEntry) => {
    try {
      const base64 = await fileToBase64(entry.file);
      const metadata = await analyzeRpgPdf(base64, entry.originalName);

      // Generate suggested filename logic
      const editionMatch = entry.originalName.match(/(\d+)/);
      const edition = editionMatch ? editionMatch[1] : "00";

      // Extract a simple folder tag from relative path if possible
      const pathParts = entry.relativePath.split('/');
      const folderTag = pathParts.length > 1 ? pathParts[0].substring(0,6).replace(/[^a-zA-Z0-9]/g, '').toUpperCase() : "ROOT";

      const suffix = metadata.filename_suffix.replace(/[^a-zA-Z0-9_]/g, '_').substring(0, 50);
      const newName = `DB_${edition}_${folderTag}_${suffix}.pdf`;

      setLibrary(prev => prev.map(item => 
        item.id === entry.id 
          ? { ...item, status: 'done', metadata, suggestedName: newName } 
          : item
      ));

    } catch (error: any) {
      console.error(`Error processing ${entry.originalName}:`, error);
      setLibrary(prev => prev.map(item => 
        item.id === entry.id 
          ? { ...item, status: 'error', error: error.message } 
          : item
      ));
    } finally {
      setProcessingQueue(prev => prev.filter(id => id !== entry.id));
    }
  }, []);

  // --- Queue Management ---
  useEffect(() => {
    const nextItem = library.find(item => item.status === 'pending' && !processingQueue.includes(item.id));

    // Process 1 at a time to be safe with Rate Limits and Browser Memory
    if (nextItem && processingQueue.length < 1) { 
      setProcessingQueue(prev => [...prev, nextItem.id]);
      setLibrary(prev => prev.map(i => i.id === nextItem.id ? { ...i, status: 'analyzing' } : i));
      processFile(nextItem);
    }
  }, [library, processingQueue, processFile]);

  // --- Batch Renaming Logic ---
  const handleRenameBatch = async () => {
    // Check if we have native handles (renaming enabled) or just File objects (fallback)
    const canRename = library.some(i => i.handle !== null);

    if (!canRename) {
      alert("⚠️ Modo de Leitura Apenas\n\nDevido a restrições de segurança do navegador (ex: rodando em iframe ou browser incompatível), o acesso de escrita ao disco está bloqueado.\n\nA renomeação automática não pode ser aplicada. Utilize o botão 'Exportar JSON' para salvar os dados.");
      return;
    }

    if (!window.confirm("Isso renomeará os arquivos no seu disco permanentemente. Deseja continuar?")) return;

    setIsRenaming(true);
    const toRename = library.filter(i => i.status === 'done' && i.suggestedName !== i.originalName);

    for (const item of toRename) {
      try {
        await renameFileOnDisk(item);
        setLibrary(prev => prev.map(i => i.id === item.id ? { ...i, status: 'renamed' } : i));
      } catch (e: any) {
        console.error(`Falha ao renomear ${item.originalName}:`, e);
        // Do not stop the queue, just log error
      }
    }
    setIsRenaming(false);
  };

  // --- Resume / Import Logic ---
  const handleImportJSON = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (Array.isArray(json)) {
          setResumeData(json as ExportedEntry[]);
        } else {
          alert("Arquivo JSON inválido.");
        }
      } catch (err) {
        console.error(err);
        alert("Erro ao ler o arquivo JSON.");
      }
    };
    reader.readAsText(file);
    // Reset input
    e.target.value = '';
  };

  const handleEntriesLoaded = (freshEntries: LibraryEntry[]) => {
    let mergedEntries = freshEntries;

    if (resumeData) {
       // --- Reconciliation Logic ---
       // Create maps for O(1) lookup
       // Map 1: Original Path -> History Data (for files not yet renamed)
       const historyByOriginalPath = new Map(resumeData.map(r => [r.path, r]));

       // Map 2: New Name + Path Context -> History Data (for files ALREADY renamed on disk)
       // We need to construct what the relativePath WOULD be if the file is renamed
       const historyByNewPath = new Map<string, ExportedEntry>();
       resumeData.forEach(r => {
          if (r.new && r.status === 'renamed') {
             // Assuming relativePath structure: "Folder/Subfolder/OriginalName.pdf"
             // New path: "Folder/Subfolder/NewName.pdf"
             const pathParts = r.path.split('/');
             pathParts.pop(); // remove original filename
             const dirPath = pathParts.join('/');
             const newRelativePath = dirPath ? `${dirPath}/${r.new}` : r.new;
             historyByNewPath.set(newRelativePath, r);
          }
       });

       mergedEntries = freshEntries.map(entry => {
          // Check 1: Is this file exactly as it was originally?
          const originalMatch = historyByOriginalPath.get(entry.relativePath);
          if (originalMatch && originalMatch.metadata) {
             return {
               ...entry,
               status: 'done', // Mark as done so we don't re-analyze
               metadata: originalMatch.metadata,
               suggestedName: originalMatch.new
             };
          }

          // Check 2: Was this file already renamed on disk?
          // If so, entry.relativePath will match the calculated new path from history
          const renamedMatch = historyByNewPath.get(entry.relativePath);
          if (renamedMatch && renamedMatch.metadata) {
             return {
                ...entry,
                status: 'renamed', // Already renamed on disk
                metadata: renamedMatch.metadata,
                suggestedName: renamedMatch.new // Should match entry.originalName/entry.name essentially
             };
          }

          return entry;
       });

       setResumeData(null); // Clear resume data after applying
    }

    setLibrary(prev => [...prev, ...mergedEntries]);
    setAppState(AppState.DASHBOARD);
  };

  // --- Render Helpers ---

  const processingCount = library.filter(i => i.status === 'pending' || i.status === 'analyzing').length;
  const progressPercent = library.length > 0 
    ? ((library.length - processingCount) / library.length) * 100 
    : 0;

  return (
    <div className="flex flex-col h-screen bg-slate-50">

      {/* Hidden Import Input */}
      <input 
        type="file" 
        accept=".json" 
        ref={importInputRef} 
        className="hidden" 
        onChange={handleImportJSON} 
      />

      {/* Header */}
      <nav className="w-full px-6 py-3 flex items-center justify-between border-b border-slate-200 bg-white z-50 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="bg-brand-600 p-2 rounded-lg">
            <BrainCircuit className="text-white w-6 h-6" />
          </div>
          <div className="flex flex-col">
            <span className="text-lg font-bold text-slate-800 leading-tight">
              T20 RPG Indexer
            </span>
            <span className="text-xs text-slate-500">Local File System Edition</span>
          </div>
        </div>

        {/* Global Status Indicator */}
        <div className="flex items-center gap-4">
           {processingCount > 0 && (
             <div className="flex items-center gap-3 bg-brand-50 px-3 py-1.5 rounded-full border border-brand-100">
               <Loader2 className="w-4 h-4 text-brand-600 animate-spin" />
               <div className="flex flex-col min-w-[120px]">
                 <span className="text-xs font-semibold text-brand-700">Indexando... {library.length - processingCount}/{library.length}</span>
                 <div className="w-full bg-brand-200 rounded-full h-1 mt-1">
                   <div className="bg-brand-500 h-1 rounded-full transition-all duration-300" style={{ width: `${progressPercent}%` }}></div>
                 </div>
               </div>
             </div>
           )}
           <div className="hidden sm:flex items-center gap-2 text-xs text-slate-500 bg-slate-100 px-3 py-1 rounded-md">
            <Sparkles size={12} className="text-brand-500" />
            <span>Gemini 2.0 Flash</span>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden p-6 max-w-[1600px] w-full mx-auto">

        {appState === AppState.IDLE ? (
          <div className="h-full flex flex-col items-center justify-center animate-fade-in-up">
            <div className="text-center space-y-6 max-w-2xl">
              <h1 className="text-4xl font-extrabold text-slate-900">
                Organize seu acervo local <br/>
                <span className="text-brand-600">direto no navegador.</span>
              </h1>

              {!resumeData ? (
                 <>
                    <p className="text-lg text-slate-600">
                      Selecione uma pasta raiz. A IA analisará recursivamente, gerará metadados e renomeará seus arquivos para manter tudo organizado.
                    </p>
                    <div className="bg-yellow-50 border border-yellow-200 p-4 rounded-lg text-sm text-yellow-800 text-left mx-auto max-w-lg">
                      <strong>Nota Importante:</strong> A renomeação automática de arquivos requer um navegador compatível com a API de Sistema de Arquivos (Chrome/Edge em Desktop).
                    </div>
                 </>
              ) : (
                 <div className="bg-green-50 border border-green-200 p-6 rounded-xl animate-fade-in text-left mx-auto max-w-xl shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                      <div className="p-2 bg-green-100 rounded-full text-green-600">
                        <RefreshCw size={24} />
                      </div>
                      <h3 className="text-lg font-bold text-green-800">Backup Carregado!</h3>
                    </div>
                    <p className="text-green-700 mb-4">
                      Dados de {resumeData.length} arquivos recuperados. 
                    </p>
                    <p className="text-slate-600 text-sm mb-4">
                      Agora, por favor, <strong>selecione novamente a mesma pasta raiz</strong> para que possamos reconectar os arquivos físicos aos dados recuperados e continuar o processo.
                    </p>
                 </div>
              )}

              <div className="pt-4 w-full max-w-xl mx-auto space-y-4">
                <FileUpload onEntriesLoaded={handleEntriesLoaded} />

                {!resumeData && (
                  <button 
                    onClick={() => importInputRef.current?.click()}
                    className="flex items-center justify-center gap-2 w-full py-3 text-slate-500 hover:text-brand-600 hover:bg-slate-100 rounded-lg transition-colors text-sm font-medium border border-transparent hover:border-slate-200"
                  >
                    <Upload size={16} />
                    Importar Progresso (.json)
                  </button>
                )}
              </div>
            </div>
          </div>
        ) : (
          <Dashboard 
            library={library} 
            filters={filters} 
            setFilters={setFilters} 
            onRenameClick={handleRenameBatch}
            isRenaming={isRenaming}
          />
        )}

      </main>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { BrainCircuit, Sparkles, Loader2, Plus, HardDrive, Upload, RefreshCw } from 'lucide-react';
import { AppState, LibraryEntry, FilterState, ExportedEntry } from './types';
import { fileToBase64 } from './utils/fileUtils';
import { renameFileOnDisk } from './utils/fileSystem';
import { analyzeRpgPdf } from './services/geminiService';
import { FileUpload } from './components/FileUpload';
import { Dashboard } from './components/Dashboard';

const App: React.FC = () => {
  const [library, setLibrary] = useState<LibraryEntry[]>([]);
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [isRenaming, setIsRenaming] = useState(false);

  // State for Resume/Import feature
  const [resumeData, setResumeData] = useState<ExportedEntry[] | null>(null);
  const importInputRef = useRef<HTMLInputElement>(null);

  const [filters, setFilters] = useState<FilterState>({
    system: 'Todos',
    type: 'Todos',
    search: ''
  });

  // --- File Processing Logic (AI Analysis) ---
  const processFile = useCallback(async (entry: LibraryEntry) => {
    try {
      const base64 = await fileToBase64(entry.file);
      const metadata = await analyzeRpgPdf(base64, entry.originalName);

      // Generate suggested filename logic
      const editionMatch = entry.originalName.match(/(\d+)/);
      const edition = editionMatch ? editionMatch[1] : "00";

      // Extract a simple folder tag from relative path if possible
      const pathParts = entry.relativePath.split('/');
      const folderTag = pathParts.length > 1 ? pathParts[0].substring(0,6).replace(/[^a-zA-Z0-9]/g, '').toUpperCase() : "ROOT";

      const suffix = metadata.filename_suffix.replace(/[^a-zA-Z0-9_]/g, '_').substring(0, 50);
      const newName = `DB_${edition}_${folderTag}_${suffix}.pdf`;

      setLibrary(prev => prev.map(item => 
        item.id === entry.id 
          ? { ...item, status: 'done', metadata, suggestedName: newName } 
          : item
      ));

    } catch (error: any) {
      console.error(`Error processing ${entry.originalName}:`, error);
      setLibrary(prev => prev.map(item => 
        item.id === entry.id 
          ? { ...item, status: 'error', error: error.message } 
          : item
      ));
    } finally {
      setProcessingQueue(prev => prev.filter(id => id !== entry.id));
    }
  }, []);

  // --- Queue Management ---
  useEffect(() => {
    const nextItem = library.find(item => item.status === 'pending' && !processingQueue.includes(item.id));

    // Process 1 at a time to be safe with Rate Limits and Browser Memory
    if (nextItem && processingQueue.length < 1) { 
      setProcessingQueue(prev => [...prev, nextItem.id]);
      setLibrary(prev => prev.map(i => i.id === nextItem.id ? { ...i, status: 'analyzing' } : i));
      processFile(nextItem);
    }
  }, [library, processingQueue, processFile]);

  // --- Batch Renaming Logic ---
  const handleRenameBatch = async () => {
    // Check if we have native handles (renaming enabled) or just File objects (fallback)
    const canRename = library.some(i => i.handle !== null);

    if (!canRename) {
      alert("⚠️ Modo de Leitura Apenas\n\nDevido a restrições de segurança do navegador (ex: rodando em iframe ou browser incompatível), o acesso de escrita ao disco está bloqueado.\n\nA renomeação automática não pode ser aplicada. Utilize o botão 'Exportar JSON' para salvar os dados.");
      return;
    }

    if (!window.confirm("Isso renomeará os arquivos no seu disco permanentemente. Deseja continuar?")) return;

    setIsRenaming(true);
    const toRename = library.filter(i => i.status === 'done' && i.suggestedName !== i.originalName);

    for (const item of toRename) {
      try {
        await renameFileOnDisk(item);
        setLibrary(prev => prev.map(i => i.id === item.id ? { ...i, status: 'renamed' } : i));
      } catch (e: any) {
        console.error(`Falha ao renomear ${item.originalName}:`, e);
        // Do not stop the queue, just log error
      }
    }
    setIsRenaming(false);
  };

  // --- Resume / Import Logic ---
  const handleImportJSON = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (Array.isArray(json)) {
          setResumeData(json as ExportedEntry[]);
        } else {
          alert("Arquivo JSON inválido.");
        }
      } catch (err) {
        console.error(err);
        alert("Erro ao ler o arquivo JSON.");
      }
    };
    reader.readAsText(file);
    // Reset input
    e.target.value = '';
  };

  const handleEntriesLoaded = (freshEntries: LibraryEntry[]) => {
    let mergedEntries = freshEntries;

    if (resumeData) {
       // --- Reconciliation Logic ---
       // Create maps for O(1) lookup
       // Map 1: Original Path -> History Data (for files not yet renamed)
       const historyByOriginalPath = new Map<string, ExportedEntry>(
         resumeData.map(r => [r.path, r] as [string, ExportedEntry])
       );

       // Map 2: New Name + Path Context -> History Data (for files ALREADY renamed on disk)
       // We need to construct what the relativePath WOULD be if the file is renamed
       const historyByNewPath = new Map<string, ExportedEntry>();
       resumeData.forEach(r => {
          if (r.new && r.status === 'renamed') {
             // Assuming relativePath structure: "Folder/Subfolder/OriginalName.pdf"
             // New path: "Folder/Subfolder/NewName.pdf"
             const pathParts = r.path.split('/');
             pathParts.pop(); // remove original filename
             const dirPath = pathParts.join('/');
             const newRelativePath = dirPath ? `${dirPath}/${r.new}` : r.new;
             historyByNewPath.set(newRelativePath, r);
          }
       });

       mergedEntries = freshEntries.map(entry => {
          // Check 1: Is this file exactly as it was originally?
          const originalMatch = historyByOriginalPath.get(entry.relativePath);
          if (originalMatch && originalMatch.metadata) {
             return {
               ...entry,
               status: 'done', // Mark as done so we don't re-analyze
               metadata: originalMatch.metadata,
               suggestedName: originalMatch.new
             };
          }

          // Check 2: Was this file already renamed on disk?
          // If so, entry.relativePath will match the calculated new path from history
          const renamedMatch = historyByNewPath.get(entry.relativePath);
          if (renamedMatch && renamedMatch.metadata) {
             return {
                ...entry,
                status: 'renamed', // Already renamed on disk
                metadata: renamedMatch.metadata,
                suggestedName: renamedMatch.new // Should match entry.originalName/entry.name essentially
             };
          }

          return entry;
       });

       setResumeData(null); // Clear resume data after applying
    }

    setLibrary(prev => [...prev, ...mergedEntries]);
    setAppState(AppState.DASHBOARD);
  };

  // --- Render Helpers ---

  const processingCount = library.filter(i => i.status === 'pending' || i.status === 'analyzing').length;
  const progressPercent = library.length > 0 
    ? ((library.length - processingCount) / library.length) * 100 
    : 0;

  return (
    <div className="flex flex-col h-screen bg-slate-50">

      {/* Hidden Import Input */}
      <input 
        type="file" 
        accept=".json" 
        ref={importInputRef} 
        className="hidden" 
        onChange={handleImportJSON} 
      />

      {/* Header */}
      <nav className="w-full px-6 py-3 flex items-center justify-between border-b border-slate-200 bg-white z-50 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="bg-brand-600 p-2 rounded-lg">
            <BrainCircuit className="text-white w-6 h-6" />
          </div>
          <div className="flex flex-col">
            <span className="text-lg font-bold text-slate-800 leading-tight">
              T20 RPG Indexer
            </span>
            <span className="text-xs text-slate-500">Local File System Edition</span>
          </div>
        </div>

        {/* Global Status Indicator */}
        <div className="flex items-center gap-4">
           {processingCount > 0 && (
             <div className="flex items-center gap-3 bg-brand-50 px-3 py-1.5 rounded-full border border-brand-100">
               <Loader2 className="w-4 h-4 text-brand-600 animate-spin" />
               <div className="flex flex-col min-w-[120px]">
                 <span className="text-xs font-semibold text-brand-700">Indexando... {library.length - processingCount}/{library.length}</span>
                 <div className="w-full bg-brand-200 rounded-full h-1 mt-1">
                   <div className="bg-brand-500 h-1 rounded-full transition-all duration-300" style={{ width: `${progressPercent}%` }}></div>
                 </div>
               </div>
             </div>
           )}
           <div className="hidden sm:flex items-center gap-2 text-xs text-slate-500 bg-slate-100 px-3 py-1 rounded-md">
            <Sparkles size={12} className="text-brand-500" />
            <span>Gemini 2.0 Flash</span>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden p-6 max-w-[1600px] w-full mx-auto">

        {appState === AppState.IDLE ? (
          <div className="h-full flex flex-col items-center justify-center animate-fade-in-up">
            <div className="text-center space-y-6 max-w-2xl">
              <h1 className="text-4xl font-extrabold text-slate-900">
                Organize seu acervo local <br/>
                <span className="text-brand-600">direto no navegador.</span>
              </h1>

              {!resumeData ? (
                 <>
                    <p className="text-lg text-slate-600">
                      Selecione uma pasta raiz. A IA analisará recursivamente, gerará metadados e renomeará seus arquivos para manter tudo organizado.
                    </p>
                    <div className="bg-yellow-50 border border-yellow-200 p-4 rounded-lg text-sm text-yellow-800 text-left mx-auto max-w-lg">
                      <strong>Nota Importante:</strong> A renomeação automática de arquivos requer um navegador compatível com a API de Sistema de Arquivos (Chrome/Edge em Desktop).
                    </div>
                 </>
              ) : (
                 <div className="bg-green-50 border border-green-200 p-6 rounded-xl animate-fade-in text-left mx-auto max-w-xl shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                      <div className="p-2 bg-green-100 rounded-full text-green-600">
                        <RefreshCw size={24} />
                      </div>
                      <h3 className="text-lg font-bold text-green-800">Backup Carregado!</h3>
                    </div>
                    <p className="text-green-700 mb-4">
                      Dados de {resumeData.length} arquivos recuperados. 
                    </p>
                    <p className="text-slate-600 text-sm mb-4">
                      Agora, por favor, <strong>selecione novamente a mesma pasta raiz</strong> para que possamos reconectar os arquivos físicos aos dados recuperados e continuar o processo.
                    </p>
                 </div>
              )}

              <div className="pt-4 w-full max-w-xl mx-auto space-y-4">
                <FileUpload onEntriesLoaded={handleEntriesLoaded} />

                {!resumeData && (
                  <button 
                    onClick={() => importInputRef.current?.click()}
                    className="flex items-center justify-center gap-2 w-full py-3 text-slate-500 hover:text-brand-600 hover:bg-slate-100 rounded-lg transition-colors text-sm font-medium border border-transparent hover:border-slate-200"
                  >
                    <Upload size={16} />
                    Importar Progresso (.json)
                  </button>
                )}
              </div>
            </div>
          </div>
        ) : (
          <Dashboard 
            library={library} 
            filters={filters} 
            setFilters={setFilters} 
            onRenameClick={handleRenameBatch}
            isRenaming={isRenaming}
          />
        )}

      </main>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { LibraryEntry, FilterState } from '../types';
import { Search, Filter, BookOpen, Sword, Scroll, Download, CheckCircle, Save, FolderInput, RefreshCw, Trash2, AlertTriangle } from 'lucide-react';

interface DashboardProps {
  library: LibraryEntry[];
  filters: FilterState;
  setFilters: React.Dispatch<React.SetStateAction<FilterState>>;
  onRenameClick: () => void;
  onRetryClick: () => void;
  onResetClick: () => void;
  isRenaming: boolean;
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  library, filters, setFilters, onRenameClick, onRetryClick, onResetClick, isRenaming 
}) => {

  // Calculate Metrics
  const metrics = useMemo(() => {
    const doneItems = library.filter(i => (i.status === 'done' || i.status === 'renamed') && i.metadata);
    const systems = new Set(doneItems.map(i => i.metadata?.system));
    const adventures = doneItems.filter(i => i.metadata?.type?.toLowerCase().includes('aventura'));
    const renamed = library.filter(i => i.status === 'renamed').length;
    const errors = library.filter(i => i.status === 'error').length;

    return {
      total: doneItems.length,
      systems: systems.size,
      adventures: adventures.length,
      renamed,
      errors
    };
  }, [library]);

  const availableSystems = useMemo(() => {
    const systems = new Set(library.map(i => i.metadata?.system).filter(Boolean));
    return ["Todos", ...Array.from(systems).sort()];
  }, [library]);

  const availableTypes = useMemo(() => {
    const types = new Set(library.map(i => i.metadata?.type).filter(Boolean));
    return ["Todos", ...Array.from(types).sort()];
  }, [library]);

  const filteredLibrary = useMemo(() => {
    return library.filter(item => {
      // Allow viewing errors if searching, otherwise stick to done/renamed/error/processing
      if (item.status === 'pending') return false; 

      const matchesSystem = filters.system === "Todos" || item.metadata?.system === filters.system;
      const matchesType = filters.type === "Todos" || item.metadata?.type === filters.type;
      const searchLower = filters.search.toLowerCase();

      // Fallback for metadata properties if they are null (e.g. error state)
      const summary = item.metadata?.summary?.toLowerCase() || "";

      const matchesSearch = !filters.search || 
        item.suggestedName.toLowerCase().includes(searchLower) ||
        item.originalName.toLowerCase().includes(searchLower) ||
        summary.includes(searchLower);

      return matchesSystem && matchesType && matchesSearch;
    });
  }, [library, filters]);

  const handleExport = () => {
    const dataStr = JSON.stringify(library.map(l => ({
        original: l.originalName,
        new: l.suggestedName,
        path: l.relativePath,
        metadata: l.metadata,
        status: l.status,
        processed_at: l.timestamp
    })), null, 2);

    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `rpg_library_manifest_${new Date().toISOString().slice(0,10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  const pendingRenames = library.filter(i => i.status === 'done').length;

  return (
    <div className="flex flex-col h-full gap-6">

      {/* Header Actions */}
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Acervo Digital</h2>
          <p className="text-sm text-slate-500">Gerencie, filtre e exporte sua biblioteca.</p>
        </div>

        <div className="flex flex-wrap gap-3">
             {metrics.errors > 0 && (
               <button
                 onClick={onRetryClick}
                 className="flex items-center gap-2 px-4 py-2 bg-red-50 border border-red-200 text-red-700 rounded-lg hover:bg-red-100 transition-all"
               >
                 <RefreshCw size={18} />
                 <span>Reanalisar ({metrics.errors})</span>
               </button>
             )}

             <button
              onClick={handleExport}
              className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 shadow-sm transition-all"
            >
              <Download size={18} />
              <span>Exportar JSON</span>
            </button>

            <button
              onClick={onRenameClick}
              disabled={pendingRenames === 0 || isRenaming}
              className={`
                flex items-center gap-2 px-4 py-2 rounded-lg shadow-sm text-white transition-all
                ${pendingRenames > 0 && !isRenaming ? 'bg-brand-600 hover:bg-brand-700' : 'bg-slate-300 cursor-not-allowed'}
              `}
            >
              {isRenaming ? <FolderInput size={18} className="animate-spin" /> : <Save size={18} />}
              <span>{isRenaming ? 'Renomeando...' : `Renomear (${pendingRenames})`}</span>
            </button>

            <button
              onClick={onResetClick}
              className="flex items-center gap-2 px-3 py-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
              title="Limpar tudo e reiniciar"
            >
              <Trash2 size={18} />
            </button>
        </div>
      </div>

      {/* Metrics Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
            <p className="text-xs text-slate-500 font-medium uppercase">Arquivos</p>
            <div className="flex items-center gap-2 mt-1">
                <BookOpen size={20} className="text-blue-500" />
                <span className="text-2xl font-bold text-slate-800">{metrics.total}</span>
            </div>
        </div>
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
            <p className="text-xs text-slate-500 font-medium uppercase">Sistemas</p>
            <div className="flex items-center gap-2 mt-1">
                <Scroll size={20} className="text-purple-500" />
                <span className="text-2xl font-bold text-slate-800">{metrics.systems}</span>
            </div>
        </div>
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
            <p className="text-xs text-slate-500 font-medium uppercase">Aventuras</p>
            <div className="flex items-center gap-2 mt-1">
                <Sword size={20} className="text-orange-500" />
                <span className="text-2xl font-bold text-slate-800">{metrics.adventures}</span>
            </div>
        </div>
         <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
            <p className="text-xs text-slate-500 font-medium uppercase">Renomeados</p>
            <div className="flex items-center gap-2 mt-1">
                <CheckCircle size={20} className="text-green-500" />
                <span className="text-2xl font-bold text-slate-800">{metrics.renamed}</span>
            </div>
        </div>
      </div>

      {/* Filters Toolbar */}
      <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-4 items-center">
        <div className="flex items-center gap-2 text-slate-500">
          <Filter size={18} />
          <span className="font-medium text-sm">Filtros:</span>
        </div>

        <select 
          className="bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-lg focus:ring-brand-500 focus:border-brand-500 block w-full md:w-40 p-2.5"
          value={filters.system}
          onChange={(e) => setFilters(prev => ({ ...prev, system: e.target.value }))}
        >
          {availableSystems.map(s => <option key={s} value={s}>{s}</option>)}
        </select>

        <select 
          className="bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-lg focus:ring-brand-500 focus:border-brand-500 block w-full md:w-40 p-2.5"
          value={filters.type}
          onChange={(e) => setFilters(prev => ({ ...prev, type: e.target.value }))}
        >
          {availableTypes.map(t => <option key={t} value={t}>{t}</option>)}
        </select>

        <div className="flex-1 w-full relative">
          <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
            <Search size={18} className="text-slate-400" />
          </div>
          <input 
            type="text" 
            className="bg-slate-50 border border-slate-200 text-slate-900 text-sm rounded-lg focus:ring-brand-500 focus:border-brand-500 block w-full pl-10 p-2.5" 
            placeholder="Buscar por nome, resumo ou caminho..."
            value={filters.search}
            onChange={(e) => setFilters(prev => ({ ...prev, search: e.target.value }))}
          />
        </div>
      </div>

      {/* Data Table */}
      <div className="flex-1 bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar flex-1">
          <table className="w-full text-sm text-left text-slate-600">
            <thead className="text-xs text-slate-700 uppercase bg-slate-50 border-b border-slate-200 sticky top-0">
              <tr>
                <th scope="col" className="px-6 py-3 min-w-[250px]">Arquivo (Novo vs Original)</th>
                <th scope="col" className="px-6 py-3">Status</th>
                <th scope="col" className="px-6 py-3">Sistema</th>
                <th scope="col" className="px-6 py-3">Tipo</th>
                <th scope="col" className="px-6 py-3 min-w-[300px]">Resumo</th>
              </tr>
            </thead>
            <tbody>
              {filteredLibrary.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-8 text-center text-slate-400">
                    Nenhum arquivo encontrado com os filtros atuais.
                  </td>
                </tr>
              ) : (
                filteredLibrary.map((item) => (
                  <tr key={item.id} className="bg-white border-b border-slate-100 hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 font-medium text-slate-900">
                      <div className="flex flex-col gap-1">
                        <span className={`font-semibold ${item.status === 'error' ? 'text-red-600' : 'text-brand-700'}`}>
                          {item.status === 'error' ? item.originalName : item.suggestedName}
                        </span>
                        <span className="text-xs text-slate-400 font-normal flex items-center gap-1">
                             <FolderInput size={10} /> {item.relativePath}
                        </span>
                        {item.status === 'error' && (
                          <span className="text-xs text-red-500 flex items-center gap-1 mt-1">
                            <AlertTriangle size={10} /> {item.error || 'Erro desconhecido'}
                          </span>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      {item.status === 'renamed' ? (
                          <span className="bg-green-100 text-green-800 text-xs font-medium px-2.5 py-0.5 rounded border border-green-200 flex w-fit items-center gap-1">
                              <CheckCircle size={10} /> Renomeado
                          </span>
                      ) : item.status === 'error' ? (
                          <span className="bg-red-100 text-red-800 text-xs font-medium px-2.5 py-0.5 rounded border border-red-200">
                              Erro
                          </span>
                      ) : item.status === 'done' ? (
                          <span className="bg-yellow-100 text-yellow-800 text-xs font-medium px-2.5 py-0.5 rounded border border-yellow-200">
                              Pendente
                          </span>
                      ) : (
                          <span className="bg-slate-100 text-slate-800 text-xs font-medium px-2.5 py-0.5 rounded border border-slate-200">
                             Processando
                          </span>
                      )}
                    </td>
                    <td className="px-6 py-4">
                      {item.metadata?.system && (
                        <span className="bg-blue-100 text-blue-800 text-xs font-medium px-2.5 py-0.5 rounded border border-blue-200">
                          {item.metadata?.system}
                        </span>
                      )}
                    </td>
                    <td className="px-6 py-4">{item.metadata?.type}</td>
                    <td className="px-6 py-4">
                      <p className="line-clamp-2 text-xs leading-relaxed" title={item.metadata?.summary}>
                        {item.metadata?.summary}
                      </p>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

    </div>
  );
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { BrainCircuit, Sparkles, Loader2, Plus, HardDrive, Upload, RefreshCw } from 'lucide-react';
import { AppState, LibraryEntry, FilterState, ExportedEntry } from './types';
import { fileToBase64 } from './utils/fileUtils';
import { renameFileOnDisk } from './utils/fileSystem';
import { analyzeRpgPdf } from './services/geminiService';
import { FileUpload } from './components/FileUpload';
import { Dashboard } from './components/Dashboard';

const App: React.FC = () => {
  const [library, setLibrary] = useState<LibraryEntry[]>([]);
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [isRenaming, setIsRenaming] = useState(false);

  // State for Resume/Import feature
  const [resumeData, setResumeData] = useState<ExportedEntry[] | null>(null);
  const importInputRef = useRef<HTMLInputElement>(null);

  const [filters, setFilters] = useState<FilterState>({
    system: 'Todos',
    type: 'Todos',
    search: ''
  });

  // --- File Processing Logic (AI Analysis) ---
  const processFile = useCallback(async (entry: LibraryEntry) => {
    try {
      const base64 = await fileToBase64(entry.file);
      const metadata = await analyzeRpgPdf(base64, entry.originalName);

      // Generate suggested filename logic
      const editionMatch = entry.originalName.match(/(\d+)/);
      const edition = editionMatch ? editionMatch[1] : "00";

      // Extract a simple folder tag from relative path if possible
      const pathParts = entry.relativePath.split('/');
      const folderTag = pathParts.length > 1 ? pathParts[0].substring(0,6).replace(/[^a-zA-Z0-9]/g, '').toUpperCase() : "ROOT";

      const suffix = metadata.filename_suffix.replace(/[^a-zA-Z0-9_]/g, '_').substring(0, 50);
      const newName = `DB_${edition}_${folderTag}_${suffix}.pdf`;

      setLibrary(prev => prev.map(item => 
        item.id === entry.id 
          ? { ...item, status: 'done', metadata, suggestedName: newName } 
          : item
      ));

    } catch (error: any) {
      console.error(`Error processing ${entry.originalName}:`, error);
      setLibrary(prev => prev.map(item => 
        item.id === entry.id 
          ? { ...item, status: 'error', error: error.message } 
          : item
      ));
    } finally {
      setProcessingQueue(prev => prev.filter(id => id !== entry.id));
    }
  }, []);

  // --- Queue Management ---
  useEffect(() => {
    const nextItem = library.find(item => item.status === 'pending' && !processingQueue.includes(item.id));

    // Process 1 at a time to be safe with Rate Limits and Browser Memory
    if (nextItem && processingQueue.length < 1) { 
      setProcessingQueue(prev => [...prev, nextItem.id]);
      setLibrary(prev => prev.map(i => i.id === nextItem.id ? { ...i, status: 'analyzing' } : i));
      processFile(nextItem);
    }
  }, [library, processingQueue, processFile]);

  // --- Actions: Rename, Retry, Reset ---

  const handleRenameBatch = async () => {
    const canRename = library.some(i => i.handle !== null);

    if (!canRename) {
      alert("⚠️ Modo de Leitura Apenas\n\nDevido a restrições de segurança do navegador (ex: rodando em iframe ou browser incompatível), o acesso de escrita ao disco está bloqueado.\n\nA renomeação automática não pode ser aplicada. Utilize o botão 'Exportar JSON' para salvar os dados.");
      return;
    }

    if (!window.confirm("Isso renomeará os arquivos no seu disco permanentemente. Deseja continuar?")) return;

    setIsRenaming(true);
    const toRename = library.filter(i => i.status === 'done' && i.suggestedName !== i.originalName);

    for (const item of toRename) {
      try {
        await renameFileOnDisk(item);
        setLibrary(prev => prev.map(i => i.id === item.id ? { ...i, status: 'renamed' } : i));
      } catch (e: any) {
        console.error(`Falha ao renomear ${item.originalName}:`, e);
        // Don't error out the item in UI, just log it, or could set a specific 'rename-error' status
      }
    }
    setIsRenaming(false);
  };

  const handleRetryErrors = () => {
    setLibrary(prev => prev.map(item => 
      item.status === 'error' 
        ? { ...item, status: 'pending', error: undefined } 
        : item
    ));
  };

  const handleReset = () => {
    if (!window.confirm("Isso limpará toda a lista atual. Deseja continuar?")) return;
    setLibrary([]);
    setProcessingQueue([]);
    setResumeData(null);
    setAppState(AppState.IDLE);
    setFilters({ system: 'Todos', type: 'Todos', search: '' });
  };

  // --- Resume / Import Logic ---
  const handleImportJSON = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (Array.isArray(json)) {
          setResumeData(json as ExportedEntry[]);
        } else {
          alert("Arquivo JSON inválido.");
        }
      } catch (err) {
        console.error(err);
        alert("Erro ao ler o arquivo JSON.");
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleEntriesLoaded = (freshEntries: LibraryEntry[]) => {
    let mergedEntries = freshEntries;

    if (resumeData) {
       // --- Reconciliation Logic ---
       const historyByOriginalPath = new Map<string, ExportedEntry>(
         resumeData.map(r => [r.path, r] as [string, ExportedEntry])
       );

       const historyByNewPath = new Map<string, ExportedEntry>();
       resumeData.forEach(r => {
          if (r.new && r.status === 'renamed') {
             const pathParts = r.path.split('/');
             pathParts.pop(); 
             const dirPath = pathParts.join('/');
             const newRelativePath = dirPath ? `${dirPath}/${r.new}` : r.new;
             historyByNewPath.set(newRelativePath, r);
          }
       });

       mergedEntries = freshEntries.map(entry => {
          // Check 1: Exact Match (Pending or processed but not renamed)
          const originalMatch = historyByOriginalPath.get(entry.relativePath);
          if (originalMatch && originalMatch.metadata) {
             return {
               ...entry,
               status: 'done', 
               metadata: originalMatch.metadata,
               suggestedName: originalMatch.new
             };
          }

          // Check 2: Already renamed files
          const renamedMatch = historyByNewPath.get(entry.relativePath);
          if (renamedMatch && renamedMatch.metadata) {
             return {
                ...entry,
                status: 'renamed', 
                metadata: renamedMatch.metadata,
                suggestedName: renamedMatch.new
             };
          }

          return entry;
       });

       setResumeData(null); 
    }

    setLibrary(prev => [...prev, ...mergedEntries]);
    setAppState(AppState.DASHBOARD);
  };

  // --- Render Helpers ---

  const processingCount = library.filter(i => i.status === 'pending' || i.status === 'analyzing').length;
  const progressPercent = library.length > 0 
    ? ((library.length - processingCount) / library.length) * 100 
    : 0;

  return (
    <div className="flex flex-col h-screen bg-slate-50">

      {/* Hidden Import Input */}
      <input 
        type="file" 
        accept=".json" 
        ref={importInputRef} 
        className="hidden" 
        onChange={handleImportJSON} 
      />

      {/* Header */}
      <nav className="w-full px-6 py-3 flex items-center justify-between border-b border-slate-200 bg-white z-50 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="bg-brand-600 p-2 rounded-lg">
            <BrainCircuit className="text-white w-6 h-6" />
          </div>
          <div className="flex flex-col">
            <span className="text-lg font-bold text-slate-800 leading-tight">
              T20 RPG Indexer
            </span>
            <span className="text-xs text-slate-500">Local File System Edition</span>
          </div>
        </div>

        {/* Global Status Indicator */}
        <div className="flex items-center gap-4">
           {processingCount > 0 && (
             <div className="flex items-center gap-3 bg-brand-50 px-3 py-1.5 rounded-full border border-brand-100">
               <Loader2 className="w-4 h-4 text-brand-600 animate-spin" />
               <div className="flex flex-col min-w-[120px]">
                 <span className="text-xs font-semibold text-brand-700">Indexando... {library.length - processingCount}/{library.length}</span>
                 <div className="w-full bg-brand-200 rounded-full h-1 mt-1">
                   <div className="bg-brand-500 h-1 rounded-full transition-all duration-300" style={{ width: `${progressPercent}%` }}></div>
                 </div>
               </div>
             </div>
           )}
           <div className="hidden sm:flex items-center gap-2 text-xs text-slate-500 bg-slate-100 px-3 py-1 rounded-md">
            <Sparkles size={12} className="text-brand-500" />
            <span>Gemini 2.0 Flash</span>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden p-6 max-w-[1600px] w-full mx-auto">

        {appState === AppState.IDLE ? (
          <div className="h-full flex flex-col items-center justify-center animate-fade-in-up">
            <div className="text-center space-y-6 max-w-2xl">
              <h1 className="text-4xl font-extrabold text-slate-900">
                Organize seu acervo local <br/>
                <span className="text-brand-600">direto no navegador.</span>
              </h1>

              {!resumeData ? (
                 <>
                    <p className="text-lg text-slate-600">
                      Selecione uma pasta raiz. A IA analisará recursivamente, gerará metadados e renomeará seus arquivos para manter tudo organizado.
                    </p>
                    <div className="bg-yellow-50 border border-yellow-200 p-4 rounded-lg text-sm text-yellow-800 text-left mx-auto max-w-lg">
                      <strong>Nota Importante:</strong> A renomeação automática de arquivos requer um navegador compatível com a API de Sistema de Arquivos (Chrome/Edge em Desktop).
                    </div>
                 </>
              ) : (
                 <div className="bg-green-50 border border-green-200 p-6 rounded-xl animate-fade-in text-left mx-auto max-w-xl shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                      <div className="p-2 bg-green-100 rounded-full text-green-600">
                        <RefreshCw size={24} />
                      </div>
                      <h3 className="text-lg font-bold text-green-800">Backup Carregado!</h3>
                    </div>
                    <p className="text-green-700 mb-4">
                      Dados de {resumeData.length} arquivos recuperados. 
                    </p>
                    <p className="text-slate-600 text-sm mb-4">
                      Agora, por favor, <strong>selecione novamente a mesma pasta raiz</strong> para que possamos reconectar os arquivos físicos aos dados recuperados e continuar o processo.
                    </p>
                 </div>
              )}

              <div className="pt-4 w-full max-w-xl mx-auto space-y-4">
                <FileUpload onEntriesLoaded={handleEntriesLoaded} />

                {!resumeData && (
                  <button 
                    onClick={() => importInputRef.current?.click()}
                    className="flex items-center justify-center gap-2 w-full py-3 text-slate-500 hover:text-brand-600 hover:bg-slate-100 rounded-lg transition-colors text-sm font-medium border border-transparent hover:border-slate-200"
                  >
                    <Upload size={16} />
                    Importar Progresso (.json)
                  </button>
                )}
              </div>
            </div>
          </div>
        ) : (
          <Dashboard 
            library={library} 
            filters={filters} 
            setFilters={setFilters} 
            onRenameClick={handleRenameBatch}
            onRetryClick={handleRetryErrors}
            onResetClick={handleReset}
            isRenaming={isRenaming}
          />
        )}

      </main>
    </div>
  );
};

export default App;

