  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [isRenaming, setIsRenaming] = useState(false);

  // State for Resume/Import feature
  const [resumeData, setResumeData] = useState<ExportedEntry[] | null>(null);
  const importInputRef = useRef<HTMLInputElement>(null);

  const [filters, setFilters] = useState<FilterState>({
    system: 'Todos',
    type: 'Todos',
    search: ''
  });

  // --- File Processing Logic (AI Analysis) ---
  const processFile = useCallback(async (entry: LibraryEntry) => {
    try {
      const base64 = await fileToBase64(entry.file);
      const metadata = await analyzeRpgPdf(base64, entry.originalName);

      // Generate suggested filename logic
      const editionMatch = entry.originalName.match(/(\d+)/);
      const edition = editionMatch ? editionMatch[1] : "00";

      // Extract a simple folder tag from relative path if possible
      const pathParts = entry.relativePath.split('/');
      const folderTag = pathParts.length > 1 ? pathParts[0].substring(0,6).replace(/[^a-zA-Z0-9]/g, '').toUpperCase() : "ROOT";

      const suffix = metadata.filename_suffix.replace(/[^a-zA-Z0-9_]/g, '_').substring(0, 50);
      const newName = `DB_${edition}_${folderTag}_${suffix}.pdf`;

      setLibrary(prev => prev.map(item => 
        item.id === entry.id 
          ? { ...item, status: 'done', metadata, suggestedName: newName } 
          : item
      ));

    } catch (error: any) {
      console.error(`Error processing ${entry.originalName}:`, error);
      setLibrary(prev => prev.map(item => 
        item.id === entry.id 
          ? { ...item, status: 'error', error: error.message } 
          : item
      ));
    } finally {
      setProcessingQueue(prev => prev.filter(id => id !== entry.id));
    }
  }, []);

  // --- Queue Management ---
  useEffect(() => {
    const nextItem = library.find(item => item.status === 'pending' && !processingQueue.includes(item.id));

    // Process 1 at a time to be safe with Rate Limits and Browser Memory
    if (nextItem && processingQueue.length < 1) { 
      setProcessingQueue(prev => [...prev, nextItem.id]);
      setLibrary(prev => prev.map(i => i.id === nextItem.id ? { ...i, status: 'analyzing' } : i));
      processFile(nextItem);
    }
  }, [library, processingQueue, processFile]);

  // --- Actions: Rename, Retry, Reset ---

  const handleRenameBatch = async () => {
    const canRename = library.some(i => i.handle !== null);

    if (!canRename) {
      alert("⚠️ Modo de Leitura Apenas\n\nDevido a restrições de segurança do navegador (ex: rodando em iframe ou browser incompatível), o acesso de escrita ao disco está bloqueado.\n\nA renomeação automática não pode ser aplicada. Utilize o botão 'Exportar JSON' para salvar os dados.");
      return;
    }

    if (!window.confirm("Isso renomeará os arquivos no seu disco permanentemente. Deseja continuar?")) return;

    setIsRenaming(true);
    const toRename = library.filter(i => i.status === 'done' && i.suggestedName !== i.originalName);

    for (const item of toRename) {
      try {
        await renameFileOnDisk(item);
        setLibrary(prev => prev.map(i => i.id === item.id ? { ...i, status: 'renamed' } : i));
      } catch (e: any) {
        console.error(`Falha ao renomear ${item.originalName}:`, e);
        // Don't error out the item in UI, just log it, or could set a specific 'rename-error' status
      }
    }
    setIsRenaming(false);
  };

  const handleRetryErrors = () => {
    setLibrary(prev => prev.map(item => 
      item.status === 'error' 
        ? { ...item, status: 'pending', error: undefined } 
        : item
    ));
  };

  const handleReset = () => {
    if (!window.confirm("Isso limpará toda a lista atual. Deseja continuar?")) return;
    setLibrary([]);
    setProcessingQueue([]);
    setResumeData(null);
    setAppState(AppState.IDLE);
    setFilters({ system: 'Todos', type: 'Todos', search: '' });
  };

  // --- Resume / Import Logic ---
  const handleImportJSON = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (Array.isArray(json)) {
          setResumeData(json as ExportedEntry[]);
        } else {
          alert("Arquivo JSON inválido.");
        }
      } catch (err) {
        console.error(err);
        alert("Erro ao ler o arquivo JSON.");
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleEntriesLoaded = (freshEntries: LibraryEntry[]) => {
    let mergedEntries = freshEntries;

    // Prepare history maps if resume data exists
    let historyByOriginalPath = new Map<string, ExportedEntry>();
    let historyByNewPath = new Map<string, ExportedEntry>();

    if (resumeData) {
       // Map 1: Look up by the file's ORIGINAL relative path
       historyByOriginalPath = new Map<string, ExportedEntry>(
         resumeData.map(r => [r.path, r] as [string, ExportedEntry])
       );

       // Map 2: Look up by the file's NEW relative path (if it was renamed)
       resumeData.forEach(r => {
          if (r.new && r.status === 'renamed') {
             // Reconstruct the full path as it would appear on disk now
             const pathParts = r.path.split('/');
             pathParts.pop(); // remove original filename
             const dirPath = pathParts.join('/');
             const newRelativePath = dirPath ? `${dirPath}/${r.new}` : r.new;

             historyByNewPath.set(newRelativePath, r);
          }
       });
    }

    mergedEntries = freshEntries.map(entry => {
        // PRIORITY 1: Check if this file on disk matches a file that was ALREADY RENAMED in our database.
        // If entry.relativePath (e.g., "Folder/DB_NewName.pdf") exists in historyByNewPath,
        // it means we already processed "Folder/OldName.pdf" into this file.
        const renamedMatch = historyByNewPath.get(entry.relativePath);
        if (renamedMatch && renamedMatch.metadata) {
            return {
              ...entry,
              status: 'renamed', // Correctly identified as finished based on DB
              metadata: renamedMatch.metadata,
              suggestedName: renamedMatch.new // Matches current name
            };
        }

        // PRIORITY 2: Check if this file on disk matches an ORIGINAL file in our database.
        // This happens if we processed it, but maybe didn't rename it yet, OR the rename failed.
        const originalMatch = historyByOriginalPath.get(entry.relativePath);
        if (originalMatch && originalMatch.metadata) {
            // If the DB says it's 'renamed', but we found it at the OLD path, 
            // it means the file system rename didn't actually happen (or user undid it).
            // We set it to 'done' so the user can try renaming again.
            const status = originalMatch.status === 'renamed' ? 'done' : 'done'; 

            return {
              ...entry,
              status: status as any, 
              metadata: originalMatch.metadata,
              suggestedName: originalMatch.new
            };
        }

        // PRIORITY 3: Not in database? It's a new file.
        return entry;
    });

    setResumeData(null); 
    setLibrary(prev => [...prev, ...mergedEntries]);
    setAppState(AppState.DASHBOARD);
  };

  // --- Render Helpers ---

  const processingCount = library.filter(i => i.status === 'pending' || i.status === 'analyzing').length;
  const progressPercent = library.length > 0 
    ? ((library.length - processingCount) / library.length) * 100 
    : 0;

  return (
    <div className="flex flex-col h-screen bg-slate-50">

      {/* Hidden Import Input */}
      <input 
        type="file" 
        accept=".json" 
        ref={importInputRef} 
        className="hidden" 
        onChange={handleImportJSON} 
      />

      {/* Header */}
      <nav className="w-full px-6 py-3 flex items-center justify-between border-b border-slate-200 bg-white z-50 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="bg-brand-600 p-2 rounded-lg">
            <BrainCircuit className="text-white w-6 h-6" />
          </div>
          <div className="flex flex-col">
            <span className="text-lg font-bold text-slate-800 leading-tight">
              T20 RPG Indexer
            </span>
            <span className="text-xs text-slate-500">Local File System Edition</span>
          </div>
        </div>

        {/* Global Status Indicator */}
        <div className="flex items-center gap-4">
           {processingCount > 0 && (
             <div className="flex items-center gap-3 bg-brand-50 px-3 py-1.5 rounded-full border border-brand-100">
               <Loader2 className="w-4 h-4 text-brand-600 animate-spin" />
               <div className="flex flex-col min-w-[120px]">
                 <span className="text-xs font-semibold text-brand-700">Indexando... {library.length - processingCount}/{library.length}</span>
                 <div className="w-full bg-brand-200 rounded-full h-1 mt-1">
                   <div className="bg-brand-500 h-1 rounded-full transition-all duration-300" style={{ width: `${progressPercent}%` }}></div>
                 </div>
               </div>
             </div>
           )}
           <div className="hidden sm:flex items-center gap-2 text-xs text-slate-500 bg-slate-100 px-3 py-1 rounded-md">
            <Sparkles size={12} className="text-brand-500" />
            <span>Gemini 2.0 Flash</span>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden p-6 max-w-[1600px] w-full mx-auto">

        {appState === AppState.IDLE ? (
          <div className="h-full flex flex-col items-center justify-center animate-fade-in-up">
            <div className="text-center space-y-6 max-w-2xl">
              <h1 className="text-4xl font-extrabold text-slate-900">
                Organize seu acervo local <br/>
                <span className="text-brand-600">direto no navegador.</span>
              </h1>

              {!resumeData ? (
                 <>
                    <p className="text-lg text-slate-600">
                      Selecione uma pasta raiz. A IA analisará recursivamente, gerará metadados e renomeará seus arquivos para manter tudo organizado.
                    </p>
                    <div className="bg-yellow-50 border border-yellow-200 p-4 rounded-lg text-sm text-yellow-800 text-left mx-auto max-w-lg">
                      <strong>Nota Importante:</strong> A renomeação automática de arquivos requer um navegador compatível com a API de Sistema de Arquivos (Chrome/Edge em Desktop).
                    </div>
                 </>
              ) : (
                 <div className="bg-green-50 border border-green-200 p-6 rounded-xl animate-fade-in text-left mx-auto max-w-xl shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                      <div className="p-2 bg-green-100 rounded-full text-green-600">
                        <RefreshCw size={24} />
                      </div>
                      <h3 className="text-lg font-bold text-green-800">Backup Carregado!</h3>
                    </div>
                    <p className="text-green-700 mb-4">
                      Dados de {resumeData.length} arquivos recuperados. 
                    </p>
                    <p className="text-slate-600 text-sm mb-4">
                      Agora, por favor, <strong>selecione novamente a mesma pasta raiz</strong> para que possamos reconectar os arquivos físicos aos dados recuperados e continuar o processo (apenas novos arquivos serão processados).
                    </p>
                 </div>
              )}

              <div className="pt-4 w-full max-w-xl mx-auto space-y-4">
                <FileUpload onEntriesLoaded={handleEntriesLoaded} />

                {!resumeData && (
                  <button 
                    onClick={() => importInputRef.current?.click()}
                    className="flex items-center justify-center gap-2 w-full py-3 text-slate-500 hover:text-brand-600 hover:bg-slate-100 rounded-lg transition-colors text-sm font-medium border border-transparent hover:border-slate-200"
                  >
                    <Upload size={16} />
                    Importar Progresso (.json)
                  </button>
                )}
              </div>
            </div>
          </div>
        ) : (
          <Dashboard 
            library={library} 
            filters={filters} 
            setFilters={setFilters} 
            onRenameClick={handleRenameBatch}
            onRetryClick={handleRetryErrors}
            onResetClick={handleReset}
            isRenaming={isRenaming}
          />
        )}

      </main>
    </div>
  );
};

export default App;

export enum AppState {
  IDLE = 'IDLE',
  PROCESSING = 'PROCESSING',
  DASHBOARD = 'DASHBOARD',
  ERROR = 'ERROR'
}

export interface RpgMetadata {
  official_title: string;      // Título oficial do livro (ex: "Atlas de Arton")
  system_abbreviation: string; // Sigla padronizada (ex: "T20", "DnD5e", "CoC7")
  content_type_tag: string;    // Tag curta (ex: "Core", "Sup", "Adv", "Map")
  summary: string;             // Resumo do conteúdo
  filename_slug: string;       // O título em formato snake_case limpo
  year?: string;               // Ano de publicação (opcional)
}

// Interface for Native File System Handle
export interface FileSystemFileHandle extends FileSystemHandle {
  getFile: () => Promise<File>;
  move: (newName: string) => Promise<void>;
}

export interface FileSystemDirectoryHandle extends FileSystemHandle {
  values: () => AsyncIterableIterator<FileSystemHandle>;
  getDirectoryHandle: (name: string) => Promise<FileSystemDirectoryHandle>;
  getFileHandle: (name: string) => Promise<FileSystemFileHandle>;
}

export interface LibraryEntry {
  id: string;
  handle: FileSystemFileHandle | null; // The link to the real file on disk
  file: File;
  originalName: string;
  relativePath: string; // Folder structure path
  suggestedName: string;
  metadata: RpgMetadata | null;
  status: 'pending' | 'analyzing' | 'done' | 'renamed' | 'error';
  error?: string;
  timestamp: string;
}

export interface ExportedEntry {
  original: string;
  new: string;
  path: string; // original relative path
  metadata: RpgMetadata | null;
  status: string;
  processed_at: string;
}

export interface FilterState {
  system: string;
  type: string;
  search: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { RpgMetadata } from "../types";

// Ensure API key is available
if (!process.env.API_KEY) {
  console.error("API_KEY is missing from environment variables.");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Sends a PDF base64 string to Gemini and requests structured RPG metadata.
 */
export const analyzeRpgPdf = async (base64Pdf: string, fileName: string): Promise<RpgMetadata> => {
  try {
    const modelId = 'gemini-2.0-flash-exp'; 

    const prompt = `
      Você é um Arquivista Sênior especializado em RPG de Mesa (Tabletop RPG). 
      Sua tarefa é analisar o arquivo PDF fornecido (Capa, Índice e conteúdo visual) e extrair metadados precisos para organização de arquivos digitais.

      Arquivo original: "${fileName}"

      DIRETRIZES DE ANÁLISE:

      1. **Identificação do Sistema (system_abbreviation)**:
         - Identifique o sistema de regras principal.
         - Use siglas PADRONIZADAS e CURTAS (Máx 6 chars).
         - Exemplos Obrigatórios:
           - "Tormenta 20" ou "T20" -> "T20"
           - "Dungeons & Dragons 5th Edition" -> "DnD5e"
           - "Old School Essentials" -> "OSE"
           - "Call of Cthulhu" -> "CoC"
           - "Pathfinder 2e" -> "PF2e"
           - "Vampire: The Masquerade" -> "VtM"
           - Se for genérico ou sem sistema -> "RPG"

      2. **Classificação de Tipo (content_type_tag)**:
         - Classifique o conteúdo em uma destas categorias estritas:
           - "Core" (Livro Básico, Livro do Jogador, Mestre)
           - "Sup" (Suplementos de regras, cenários, bestiários)
           - "Adv" (Aventuras, Campanhas, One-shots)
           - "Map" (Mapas, Battlegrids)
           - "Ficha" (Fichas de personagem)
           - "Zine" (Conteúdo indie curto)

      3. **Título Oficial (official_title)**:
         - O nome real do livro. Remova "PDF", "Scan", "Versão final" etc.
         - Ex: "Curse of Strahd", "O Inimigo do Mundo", "Manual Básico".

      4. **Slug para Arquivo (filename_slug)**:
         - Uma versão do Título Oficial formatada para nomes de arquivo.
         - Use Snake Case (palavras_separadas_por_underline).
         - Remova artigos desnecessários se o nome for longo.
         - Apenas caracteres alfanuméricos e underscores. Sem acentos.
         - Ex: "Atlas de Arton" -> "Atlas_de_Arton"
         - Ex: "Guia do Mestre" -> "Guia_do_Mestre"

      5. **Resumo (summary)**:
         - Um resumo de no máximo 200 caracteres focando no CONTEÚDO (Para que serve este livro?).

      Retorne APENAS o JSON.
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          { inlineData: { mimeType: 'application/pdf', data: base64Pdf } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            official_title: { type: Type.STRING },
            system_abbreviation: { type: Type.STRING },
            content_type_tag: { type: Type.STRING },
            summary: { type: Type.STRING },
            filename_slug: { type: Type.STRING },
            year: { type: Type.STRING },
          },
          required: ["official_title", "system_abbreviation", "content_type_tag", "summary", "filename_slug"]
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("A resposta da IA estava vazia.");
    }

    // Parse JSON response
    const data = JSON.parse(text) as RpgMetadata;
    return data;

  } catch (error: any) {
    console.error("Gemini API Error:", error);
    let errorMessage = "Erro ao analisar.";

    if (error.message) {
      if (error.message.includes("429")) {
        errorMessage = "Limite de requisições (429). Aguarde...";
      } else if (error.message.includes("404")) {
        errorMessage = "Modelo indisponível.";
      }
    }
    throw new Error(errorMessage);
  }
};

