import { LibraryEntry, FileSystemDirectoryHandle, FileSystemFileHandle } from '../types';

/**
 * Helper to generate a unique fingerprint for a file without reading its content.
 * Combines Relative Path + Size + LastModified.
 */
const generateFingerprint = (relativePath: string, file: File): string => {
  return `${relativePath}::${file.size}::${file.lastModified}`;
};

/**
 * Recursively reads files from a directory handle.
 */
export async function getFilesRecursively(
  dirHandle: FileSystemDirectoryHandle, 
  path = ''
): Promise<LibraryEntry[]> {
  const entries: LibraryEntry[] = [];

  // @ts-ignore
  for await (const entry of dirHandle.values()) {
    if (entry.kind === 'file') {
      const fileHandle = entry as FileSystemFileHandle;
      if (fileHandle.name.toLowerCase().endsWith('.pdf')) {
        const file = await fileHandle.getFile();
        const relativePath = path + file.name;

        entries.push({
          id: crypto.randomUUID(),
          fingerprint: generateFingerprint(relativePath, file),
          handle: fileHandle,
          file: file,
          originalName: file.name,
          relativePath: relativePath,
          size: file.size,
          lastModified: file.lastModified,
          suggestedName: 'Aguardando análise...',
          metadata: null,
          status: 'pending',
          logs: [{
            timestamp: new Date().toISOString(),
            action: 'SCAN',
            message: 'Arquivo detectado no sistema.'
          }]
        });
      }
    } else if (entry.kind === 'directory') {
      const newPath = `${path}${entry.name}/`;
      const subEntries = await getFilesRecursively(entry as FileSystemDirectoryHandle, newPath);
      entries.push(...subEntries);
    }
  }

  return entries;
}

/**
 * Converts a standard FileList (from input fallback) to LibraryEntry objects.
 */
export function processFileList(fileList: FileList): LibraryEntry[] {
  const entries: LibraryEntry[] = [];
  Array.from(fileList).forEach(file => {
    if (file.name.toLowerCase().endsWith('.pdf')) {
      const relativePath = file.webkitRelativePath || file.name;

      entries.push({
        id: crypto.randomUUID(),
        fingerprint: generateFingerprint(relativePath, file),
        handle: null,
        file: file,
        originalName: file.name,
        relativePath: relativePath,
        size: file.size,
        lastModified: file.lastModified,
        suggestedName: 'Aguardando análise...',
        metadata: null,
        status: 'pending',
        logs: [{
          timestamp: new Date().toISOString(),
          action: 'SCAN',
          message: 'Arquivo carregado via input.'
        }]
      });
    }
  });
  return entries;
}

/**
 * Renames a file on the user's disk using the File System Access API.
 */
export async function renameFileOnDisk(entry: LibraryEntry): Promise<void> {
  if (!entry.handle) {
    throw new Error("Modo de compatibilidade: O acesso direto ao disco não está disponível.");
  }

  if (!entry.suggestedName) {
    throw new Error("Nome sugerido ausente.");
  }

  // QA Check: Ensure 'move' exists before calling
  // @ts-ignore
  if (typeof entry.handle.move === 'function') {
     // @ts-ignore
     await entry.handle.move(entry.suggestedName);
  } else {
    throw new Error("Seu navegador não suporta a função 'move' nativa (API experimental). Tente usar Chrome ou Edge atualizados.");
  }
}

export enum AppState {
  IDLE = 'IDLE',
  PROCESSING = 'PROCESSING',
  DASHBOARD = 'DASHBOARD',
  ERROR = 'ERROR'
}

export interface RpgMetadata {
  official_title: string;
  system_abbreviation: string;
  content_type_tag: string;
  summary: string;
  filename_slug: string;
  year?: string;
}

export interface LogEntry {
  timestamp: string;
  action: 'SCAN' | 'ANALYZE' | 'RENAME' | 'ERROR' | 'RESTORE' | 'EDIT';
  message: string;
}

// Interface for Native File System Handle
export interface FileSystemFileHandle extends FileSystemHandle {
  getFile: () => Promise<File>;
  move: (newName: string) => Promise<void>;
}

export interface FileSystemDirectoryHandle extends FileSystemHandle {
  values: () => AsyncIterableIterator<FileSystemHandle>;
  getDirectoryHandle: (name: string) => Promise<FileSystemDirectoryHandle>;
  getFileHandle: (name: string) => Promise<FileSystemFileHandle>;
}

export interface LibraryEntry {
  id: string; // Temporary UI ID
  fingerprint: string; // Unique ID based on File Content Metadata (Size + Date + Path)
  handle: FileSystemFileHandle | null;
  file: File;

  // File System Stats
  originalName: string;
  relativePath: string;
  size: number;
  lastModified: number;

  // Processing State
  suggestedName: string;
  isManualOverride?: boolean; // New: Tracks if user manually changed the name
  metadata: RpgMetadata | null;
  status: 'pending' | 'analyzing' | 'done' | 'renamed' | 'error' | 'skipped';
  error?: string;

  // History
  logs: LogEntry[];
}

// The Persistent Database Record
export interface RegistryRecord {
  fingerprint: string;
  originalPath: string;
  currentName: string;
  fileSize: number;
  lastModified: number;
  metadata: RpgMetadata | null;
  status: string;
  isManualOverride?: boolean;
  logs: LogEntry[];
  lastUpdated: string;
}

export interface FilterState {
  system: string;
  type: string;
  search: string;
}

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { BrainCircuit, Sparkles, Loader2, Plus, HardDrive, Upload, RefreshCw } from 'lucide-react';
import { AppState, LibraryEntry, FilterState, RegistryRecord, LogEntry } from './types';
import { fileToBase64 } from './utils/fileUtils';
import { renameFileOnDisk } from './utils/fileSystem';
import { analyzeRpgPdf } from './services/geminiService';
import { FileUpload } from './components/FileUpload';
import { Dashboard } from './components/Dashboard';

const App: React.FC = () => {
  const [library, setLibrary] = useState<LibraryEntry[]>([]);
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [isRenaming, setIsRenaming] = useState(false);

  // State for Resume/Import feature - Now holds full RegistryRecords
  const [registryDB, setRegistryDB] = useState<Map<string, RegistryRecord>>(new Map());
  const [importedCount, setImportedCount] = useState<number>(0);
  const importInputRef = useRef<HTMLInputElement>(null);

  const [filters, setFilters] = useState<FilterState>({
    system: 'Todos',
    type: 'Todos',
    search: ''
  });

  // --- Helper to Append Logs ---
  const addLog = (entry: LibraryEntry, action: LogEntry['action'], message: string): LibraryEntry => {
    return {
      ...entry,
      logs: [
        ...(entry.logs || []), 
        { timestamp: new Date().toISOString(), action, message }
      ]
    };
  };

  // --- File Processing Logic (AI Analysis) ---
  const processFile = useCallback(async (entry: LibraryEntry) => {
    // Skip if user manually overrode the name or if it's already done/renamed
    if (entry.isManualOverride || entry.status === 'renamed' || entry.status === 'done') return;

    try {
      const base64 = await fileToBase64(entry.file);
      const metadata = await analyzeRpgPdf(base64, entry.originalName);

      const system = (metadata.system_abbreviation || "RPG").replace(/[^a-zA-Z0-9]/g, '');
      const type = (metadata.content_type_tag || "Doc").replace(/[^a-zA-Z0-9]/g, '');
      const slug = (metadata.filename_slug || "Unknown").replace(/[^a-zA-Z0-9_]/g, '');

      const newName = `${system}_${type}_${slug}.pdf`;

      setLibrary(prev => prev.map(item => {
        if (item.id === entry.id) {
          const updated = addLog(item, 'ANALYZE', `Metadados gerados: ${metadata.official_title}`);
          return { ...updated, status: 'done', metadata, suggestedName: newName };
        }
        return item;
      }));

    } catch (error: any) {
      console.error(`Error processing ${entry.originalName}:`, error);
      setLibrary(prev => prev.map(item => {
        if (item.id === entry.id) {
          const updated = addLog(item, 'ERROR', error.message || "Erro na análise");
          return { ...updated, status: 'error', error: error.message };
        }
        return item;
      }));
    } finally {
      setProcessingQueue(prev => prev.filter(id => id !== entry.id));
    }
  }, []);

  // --- Queue Management (Concurrency optimized to 3) ---
  useEffect(() => {
    const CONCURRENCY_LIMIT = 3;
    const processingCount = library.filter(item => item.status === 'analyzing').length;

    if (processingCount < CONCURRENCY_LIMIT) {
      const nextItems = library
        .filter(item => item.status === 'pending' && !processingQueue.includes(item.id))
        .slice(0, CONCURRENCY_LIMIT - processingCount);

      if (nextItems.length > 0) {
        const nextIds = nextItems.map(i => i.id);
        setProcessingQueue(prev => [...prev, ...nextIds]);

        // Mark as analyzing immediately to prevent double selection in next render
        setLibrary(prev => prev.map(i => nextIds.includes(i.id) ? { ...i, status: 'analyzing' } : i));

        // Trigger process
        nextItems.forEach(item => processFile(item));
      }
    }
  }, [library, processingQueue, processFile]);

  // --- Actions: Rename, Manual Edit, Retry, Reset ---

  const handleManualEdit = (id: string, newName: string) => {
    setLibrary(prev => prev.map(item => {
      if (item.id === id) {
        // Log the manual change
        const updated = addLog(item, 'EDIT', `Nome editado manualmente de '${item.suggestedName}' para '${newName}'`);
        return {
          ...updated,
          suggestedName: newName,
          isManualOverride: true,
          status: 'done' // Ensure it's ready for renaming
        };
      }
      return item;
    }));
  };

  const handleSingleRename = async (id: string) => {
    const item = library.find(i => i.id === id);
    if (!item || !item.handle) {
      alert("Arquivo não acessível para escrita.");
      return;
    }

    try {
      await renameFileOnDisk(item);
      setLibrary(prev => prev.map(i => {
        if (i.id === id) {
          const updated = addLog(i, 'RENAME', `Renomeado individualmente para ${i.suggestedName}`);
          return { ...updated, status: 'renamed' };
        }
        return i;
      }));
    } catch (e: any) {
      console.error(`Erro ao renomear ${item.originalName}:`, e);
      alert(`Erro: ${e.message}`);
      setLibrary(prev => prev.map(i => {
        if (i.id === id) return addLog(i, 'ERROR', `Falha ao renomear: ${e.message}`);
        return i;
      }));
    }
  };

  const handleRenameBatch = async () => {
    const canRename = library.some(i => i.handle !== null);

    if (!canRename) {
      alert("⚠️ Modo de Leitura Apenas\n\nO acesso de escrita ao disco está bloqueado.");
      return;
    }

    const toRename = library.filter(i => i.status === 'done' && i.suggestedName !== i.originalName);
    if (toRename.length === 0) return;

    if (!window.confirm(`Isso renomeará ${toRename.length} arquivos permanentemente. Deseja continuar?`)) return;

    setIsRenaming(true);

    for (const item of toRename) {
      try {
        await renameFileOnDisk(item);

        setLibrary(prev => prev.map(i => {
           if (i.id === item.id) {
             const updated = addLog(i, 'RENAME', `Renomeado em lote para ${i.suggestedName}`);
             return { ...updated, status: 'renamed' };
           }
           return i;
        }));

      } catch (e: any) {
        console.error(`Falha ao renomear ${item.originalName}:`, e);
        setLibrary(prev => prev.map(i => {
           if (i.id === item.id) {
             return addLog(i, 'ERROR', `Falha ao renomear: ${e.message}`);
           }
           return i;
        }));
      }
    }
    setIsRenaming(false);
  };

  const handleRetryErrors = () => {
    setLibrary(prev => prev.map(item => 
      item.status === 'error' 
        ? { ...item, status: 'pending', error: undefined, logs: [...item.logs, { timestamp: new Date().toISOString(), action: 'RESTORE', message: 'Tentativa de reprocessamento.'}] } 
        : item
    ));
  };

  const handleReset = () => {
    if (!window.confirm("Isso limpará toda a lista atual. Deseja continuar?")) return;
    setLibrary([]);
    setProcessingQueue([]);
    setRegistryDB(new Map());
    setImportedCount(0);
    setAppState(AppState.IDLE);
    setFilters({ system: 'Todos', type: 'Todos', search: '' });
  };

  // --- Resume / Import Logic ---
  const handleImportJSON = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (Array.isArray(json)) {
          // Build the Registry Map using Fingerprint as Key
          const newRegistry = new Map<string, RegistryRecord>();
          json.forEach((record: RegistryRecord) => {
             if (record.fingerprint) {
                newRegistry.set(record.fingerprint, record);
             }
          });

          setRegistryDB(newRegistry);
          setImportedCount(newRegistry.size);
        } else {
          alert("Banco de dados JSON inválido.");
        }
      } catch (err) {
        console.error(err);
        alert("Erro ao ler o arquivo JSON.");
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleEntriesLoaded = (freshEntries: LibraryEntry[]) => {
    // Create an auxiliary index for lookup by Current Name
    const dbByFilename = new Map<string, RegistryRecord>();
    registryDB.forEach(record => {
      if (record.currentName) {
        dbByFilename.set(record.currentName, record);
      }
    });

    const mergedEntries = freshEntries.map(entry => {
        // PRIORITY 1: Exact Fingerprint Match
        const fpRecord = registryDB.get(entry.fingerprint);
        if (fpRecord) {
            return {
              ...entry,
              status: fpRecord.status === 'renamed' ? 'renamed' : 'done',
              metadata: fpRecord.metadata,
              suggestedName: fpRecord.currentName,
              isManualOverride: fpRecord.isManualOverride,
              logs: [...(fpRecord.logs || []), { timestamp: new Date().toISOString(), action: 'RESTORE', message: 'Registro recuperado (Fingerprint).' }]
            } as LibraryEntry;
        }

        // PRIORITY 2: Filename Match
        const nameRecord = dbByFilename.get(entry.originalName);
        if (nameRecord) {
           return {
             ...entry,
             status: 'renamed', 
             metadata: nameRecord.metadata,
             suggestedName: nameRecord.currentName,
             isManualOverride: nameRecord.isManualOverride,
             logs: [...(nameRecord.logs || []), { timestamp: new Date().toISOString(), action: 'RESTORE', message: 'Registro recuperado (Nome de Arquivo).' }]
           } as LibraryEntry;
        }

        // New File
        return entry;
    });

    setLibrary(prev => [...prev, ...mergedEntries]);
    setAppState(AppState.DASHBOARD);
  };

  // --- Render Helpers ---

  const processingCount = library.filter(i => i.status === 'pending' || i.status === 'analyzing').length;
  const progressPercent = library.length > 0 
    ? ((library.length - processingCount) / library.length) * 100 
    : 0;

  return (
    <div className="flex flex-col h-screen bg-slate-50">

      <input 
        type="file" 
        accept=".json" 
        ref={importInputRef} 
        className="hidden" 
        onChange={handleImportJSON} 
      />

      {/* Header */}
      <nav className="w-full px-6 py-3 flex items-center justify-between border-b border-slate-200 bg-white z-50 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="bg-brand-600 p-2 rounded-lg">
            <BrainCircuit className="text-white w-6 h-6" />
          </div>
          <div className="flex flex-col">
            <span className="text-lg font-bold text-slate-800 leading-tight">
              T20 RPG Indexer
            </span>
            <span className="text-xs text-slate-500">Local File System Edition</span>
          </div>
        </div>

        <div className="flex items-center gap-4">
           {processingCount > 0 && (
             <div className="flex items-center gap-3 bg-brand-50 px-3 py-1.5 rounded-full border border-brand-100">
               <Loader2 className="w-4 h-4 text-brand-600 animate-spin" />
               <div className="flex flex-col min-w-[120px]">
                 <span className="text-xs font-semibold text-brand-700">Indexando... {library.length - processingCount}/{library.length}</span>
                 <div className="w-full bg-brand-200 rounded-full h-1 mt-1">
                   <div className="bg-brand-500 h-1 rounded-full transition-all duration-300" style={{ width: `${progressPercent}%` }}></div>
                 </div>
               </div>
             </div>
           )}
           <div className="hidden sm:flex items-center gap-2 text-xs text-slate-500 bg-slate-100 px-3 py-1 rounded-md">
            <Sparkles size={12} className="text-brand-500" />
            <span>Gemini 2.0 Flash</span>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden p-6 max-w-[1600px] w-full mx-auto">

        {appState === AppState.IDLE ? (
          <div className="h-full flex flex-col items-center justify-center animate-fade-in-up">
            <div className="text-center space-y-6 max-w-2xl">
              <h1 className="text-4xl font-extrabold text-slate-900">
                Organize seu acervo local <br/>
                <span className="text-brand-600">direto no navegador.</span>
              </h1>

              {importedCount === 0 ? (
                 <>
                    <p className="text-lg text-slate-600">
                      Selecione uma pasta raiz. A IA analisará recursivamente, gerará metadados e criará um registro histórico permanente.
                    </p>
                    <div className="bg-yellow-50 border border-yellow-200 p-4 rounded-lg text-sm text-yellow-800 text-left mx-auto max-w-lg">
                      <strong>Nota Importante:</strong> A renomeação automática de arquivos requer um navegador compatível com a API de Sistema de Arquivos (Chrome/Edge em Desktop).
                    </div>
                 </>
              ) : (
                 <div className="bg-green-50 border border-green-200 p-6 rounded-xl animate-fade-in text-left mx-auto max-w-xl shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                      <div className="p-2 bg-green-100 rounded-full text-green-600">
                        <RefreshCw size={24} />
                      </div>
                      <h3 className="text-lg font-bold text-green-800">Database Carregado!</h3>
                    </div>
                    <p className="text-green-700 mb-4">
                      {importedCount} registros históricos identificados.
                    </p>
                    <p className="text-slate-600 text-sm mb-4">
                      Selecione a pasta raiz novamente. O sistema irá comparar os arquivos físicos com o banco de dados e ignorar os já processados ou renomeados.
                    </p>
                 </div>
              )}

              <div className="pt-4 w-full max-w-xl mx-auto space-y-4">
                <FileUpload onEntriesLoaded={handleEntriesLoaded} />

                {importedCount === 0 && (
                  <button 
                    onClick={() => importInputRef.current?.click()}
                    className="flex items-center justify-center gap-2 w-full py-3 text-slate-500 hover:text-brand-600 hover:bg-slate-100 rounded-lg transition-colors text-sm font-medium border border-transparent hover:border-slate-200"
                  >
                    <Upload size={16} />
                    Carregar Database (.json)
                  </button>
                )}
              </div>
            </div>
          </div>
        ) : (
          <Dashboard 
            library={library} 
            filters={filters} 
            setFilters={setFilters} 
            onRenameClick={handleRenameBatch}
            onRetryClick={handleRetryErrors}
            onResetClick={handleReset}
            onManualEdit={handleManualEdit}
            onSingleRename={handleSingleRename}
            isRenaming={isRenaming}
          />
        )}

      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState } from 'react';
import { LibraryEntry, FilterState, RegistryRecord } from '../types';
import { Search, Filter, BookOpen, Sword, Scroll, Download, CheckCircle, Save, FolderInput, RefreshCw, Trash2, AlertTriangle, FileClock, Pencil, X, Play, UserCheck } from 'lucide-react';

interface DashboardProps {
  library: LibraryEntry[];
  filters: FilterState;
  setFilters: React.Dispatch<React.SetStateAction<FilterState>>;
  onRenameClick: () => void;
  onRetryClick: () => void;
  onResetClick: () => void;
  onManualEdit: (id: string, newName: string) => void;
  onSingleRename: (id: string) => void;
  isRenaming: boolean;
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  library, filters, setFilters, onRenameClick, onRetryClick, onResetClick, onManualEdit, onSingleRename, isRenaming 
}) => {

  // State for inline editing
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState<string>("");

  // Calculate Metrics
  const metrics = useMemo(() => {
    const doneItems = library.filter(i => (i.status === 'done' || i.status === 'renamed' || i.status === 'skipped') && i.metadata);
    const systems = new Set(doneItems.map(i => i.metadata?.system_abbreviation));
    const adventures = doneItems.filter(i => i.metadata?.content_type_tag === 'Adv');
    const renamed = library.filter(i => i.status === 'renamed').length;
    const errors = library.filter(i => i.status === 'error').length;

    return {
      total: doneItems.length,
      systems: systems.size,
      adventures: adventures.length,
      renamed,
      errors
    };
  }, [library]);

  const availableSystems = useMemo(() => {
    const systems = new Set(library.map(i => i.metadata?.system_abbreviation).filter(Boolean));
    return ["Todos", ...Array.from(systems).sort()];
  }, [library]);

  const availableTypes = useMemo(() => {
    const types = new Set(library.map(i => i.metadata?.content_type_tag).filter(Boolean));
    return ["Todos", ...Array.from(types).sort()];
  }, [library]);

  const filteredLibrary = useMemo(() => {
    return library.filter(item => {
      // Allow viewing errors if searching
      if (item.status === 'pending') return false; 

      const matchesSystem = filters.system === "Todos" || item.metadata?.system_abbreviation === filters.system;
      const matchesType = filters.type === "Todos" || item.metadata?.content_type_tag === filters.type;
      const searchLower = filters.search.toLowerCase();

      const summary = item.metadata?.summary?.toLowerCase() || "";
      const title = item.metadata?.official_title?.toLowerCase() || "";

      const matchesSearch = !filters.search || 
        item.suggestedName.toLowerCase().includes(searchLower) ||
        item.originalName.toLowerCase().includes(searchLower) ||
        title.includes(searchLower) ||
        summary.includes(searchLower);

      return matchesSystem && matchesType && matchesSearch;
    });
  }, [library, filters]);

  const handleExport = () => {
    // Export strict RegistryRecord format
    const dbExport: RegistryRecord[] = library.map(l => ({
        fingerprint: l.fingerprint,
        originalPath: l.relativePath,
        currentName: l.suggestedName,
        fileSize: l.size,
        lastModified: l.lastModified,
        metadata: l.metadata,
        status: l.status,
        isManualOverride: l.isManualOverride,
        logs: l.logs,
        lastUpdated: new Date().toISOString()
    }));

    const dataStr = JSON.stringify(dbExport, null, 2);

    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `rpg_library_database_${new Date().toISOString().slice(0,10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  const startEditing = (item: LibraryEntry) => {
    setEditingId(item.id);
    setEditValue(item.suggestedName);
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditValue("");
  };

  const saveEditing = (id: string) => {
    if (editValue.trim()) {
      onManualEdit(id, editValue.trim());
    }
    setEditingId(null);
    setEditValue("");
  };

  const pendingRenames = library.filter(i => i.status === 'done').length;

  return (
    <div className="flex flex-col h-full gap-6">

      {/* Header Actions */}
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Acervo Digital</h2>
          <p className="text-sm text-slate-500">Gerencie, filtre e salve o banco de dados.</p>
        </div>

        <div className="flex flex-wrap gap-3">
             {metrics.errors > 0 && (
               <button
                 onClick={onRetryClick}
                 className="flex items-center gap-2 px-4 py-2 bg-red-50 border border-red-200 text-red-700 rounded-lg hover:bg-red-100 transition-all"
               >
                 <RefreshCw size={18} />
                 <span>Reanalisar ({metrics.errors})</span>
               </button>
             )}

             <button
              onClick={handleExport}
              className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 shadow-sm transition-all"
            >
              <Download size={18} />
              <span>Salvar Database</span>
            </button>

            <button
              onClick={onRenameClick}
              disabled={pendingRenames === 0 || isRenaming}
              className={`
                flex items-center gap-2 px-4 py-2 rounded-lg shadow-sm text-white transition-all
                ${pendingRenames > 0 && !isRenaming ? 'bg-brand-600 hover:bg-brand-700' : 'bg-slate-300 cursor-not-allowed'}
              `}
            >
              {isRenaming ? <FolderInput size={18} className="animate-spin" /> : <Save size={18} />}
              <span>{isRenaming ? 'Renomeando...' : `Renomear Lote (${pendingRenames})`}</span>
            </button>

            <button
              onClick={onResetClick}
              className="flex items-center gap-2 px-3 py-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
              title="Limpar tudo e reiniciar"
            >
              <Trash2 size={18} />
            </button>
        </div>
      </div>

      {/* Metrics Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
            <p className="text-xs text-slate-500 font-medium uppercase">Arquivos</p>
            <div className="flex items-center gap-2 mt-1">
                <BookOpen size={20} className="text-blue-500" />
                <span className="text-2xl font-bold text-slate-800">{metrics.total}</span>
            </div>
        </div>
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
            <p className="text-xs text-slate-500 font-medium uppercase">Sistemas</p>
            <div className="flex items-center gap-2 mt-1">
                <Scroll size={20} className="text-purple-500" />
                <span className="text-2xl font-bold text-slate-800">{metrics.systems}</span>
            </div>
        </div>
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
            <p className="text-xs text-slate-500 font-medium uppercase">Aventuras</p>
            <div className="flex items-center gap-2 mt-1">
                <Sword size={20} className="text-orange-500" />
                <span className="text-2xl font-bold text-slate-800">{metrics.adventures}</span>
            </div>
        </div>
         <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
            <p className="text-xs text-slate-500 font-medium uppercase">Renomeados</p>
            <div className="flex items-center gap-2 mt-1">
                <CheckCircle size={20} className="text-green-500" />
                <span className="text-2xl font-bold text-slate-800">{metrics.renamed}</span>
            </div>
        </div>
      </div>

      {/* Filters Toolbar */}
      <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-4 items-center">
        <div className="flex items-center gap-2 text-slate-500">
          <Filter size={18} />
          <span className="font-medium text-sm">Filtros:</span>
        </div>

        <select 
          className="bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-lg focus:ring-brand-500 focus:border-brand-500 block w-full md:w-40 p-2.5"
          value={filters.system}
          onChange={(e) => setFilters(prev => ({ ...prev, system: e.target.value }))}
        >
          {availableSystems.map(s => <option key={s} value={s}>{s}</option>)}
        </select>

        <select 
          className="bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-lg focus:ring-brand-500 focus:border-brand-500 block w-full md:w-40 p-2.5"
          value={filters.type}
          onChange={(e) => setFilters(prev => ({ ...prev, type: e.target.value }))}
        >
          {availableTypes.map(t => <option key={t} value={t}>{t}</option>)}
        </select>

        <div className="flex-1 w-full relative">
          <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
            <Search size={18} className="text-slate-400" />
          </div>
          <input 
            type="text" 
            className="bg-slate-50 border border-slate-200 text-slate-900 text-sm rounded-lg focus:ring-brand-500 focus:border-brand-500 block w-full pl-10 p-2.5" 
            placeholder="Buscar por título, sistema ou arquivo..."
            value={filters.search}
            onChange={(e) => setFilters(prev => ({ ...prev, search: e.target.value }))}
          />
        </div>
      </div>

      {/* Data Table */}
      <div className="flex-1 bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar flex-1">
          <table className="w-full text-sm text-left text-slate-600">
            <thead className="text-xs text-slate-700 uppercase bg-slate-50 border-b border-slate-200 sticky top-0">
              <tr>
                <th scope="col" className="px-6 py-3 min-w-[300px]">Arquivo (Sugestão vs Original)</th>
                <th scope="col" className="px-6 py-3">Status</th>
                <th scope="col" className="px-6 py-3">Sistema</th>
                <th scope="col" className="px-6 py-3">Tipo</th>
                <th scope="col" className="px-6 py-3 min-w-[250px]">Título & Resumo</th>
              </tr>
            </thead>
            <tbody>
              {filteredLibrary.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-8 text-center text-slate-400">
                    Nenhum arquivo encontrado com os filtros atuais.
                  </td>
                </tr>
              ) : (
                filteredLibrary.map((item) => (
                  <tr key={item.id} className="bg-white border-b border-slate-100 hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 font-medium text-slate-900">
                      <div className="flex flex-col gap-1">
                        {editingId === item.id ? (
                           <div className="flex items-center gap-2">
                             <input 
                               type="text"
                               autoFocus
                               className="border border-brand-400 rounded px-2 py-1 text-sm w-full focus:outline-none focus:ring-2 focus:ring-brand-200"
                               value={editValue}
                               onChange={(e) => setEditValue(e.target.value)}
                               onKeyDown={(e) => {
                                 if (e.key === 'Enter') saveEditing(item.id);
                                 if (e.key === 'Escape') cancelEditing();
                               }}
                             />
                             <button onClick={() => saveEditing(item.id)} className="text-green-600 hover:bg-green-100 p-1 rounded"><CheckCircle size={16}/></button>
                             <button onClick={cancelEditing} className="text-red-500 hover:bg-red-100 p-1 rounded"><X size={16}/></button>
                           </div>
                        ) : (
                          <div className="flex items-center gap-2 group">
                             <span className={`font-semibold ${item.status === 'error' ? 'text-red-600' : 'text-brand-700'}`}>
                                {item.status === 'error' ? item.originalName : item.suggestedName}
                             </span>
                             {item.status === 'done' && (
                                <button 
                                  onClick={() => startEditing(item)} 
                                  className="opacity-0 group-hover:opacity-100 text-slate-400 hover:text-brand-600 transition-opacity"
                                  title="Editar nome manualmente"
                                >
                                  <Pencil size={14} />
                                </button>
                             )}
                          </div>
                        )}

                        <span className="text-xs text-slate-400 font-normal flex items-center gap-1 truncate max-w-[300px]" title={item.relativePath}>
                             <FolderInput size={10} /> {item.relativePath}
                        </span>

                        {item.isManualOverride && (
                           <span className="text-[10px] text-orange-600 flex items-center gap-1 mt-0.5 bg-orange-50 w-fit px-1.5 py-0.5 rounded border border-orange-100">
                             <UserCheck size={10} /> Editado manualmente
                           </span>
                        )}

                        {item.status === 'error' && (
                          <span className="text-xs text-red-500 flex items-center gap-1 mt-1">
                            <AlertTriangle size={10} /> {item.error || 'Erro desconhecido'}
                          </span>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex flex-col gap-2 items-start">
                        {item.status === 'renamed' ? (
                            <span className="bg-green-100 text-green-800 text-xs font-medium px-2.5 py-0.5 rounded border border-green-200 flex w-fit items-center gap-1">
                                <CheckCircle size={10} /> Renomeado
                            </span>
                        ) : item.status === 'error' ? (
                            <span className="bg-red-100 text-red-800 text-xs font-medium px-2.5 py-0.5 rounded border border-red-200">
                                Erro
                            </span>
                        ) : item.status === 'done' ? (
                            <span className="bg-yellow-100 text-yellow-800 text-xs font-medium px-2.5 py-0.5 rounded border border-yellow-200">
                                Pendente
                            </span>
                        ) : (
                            <span className="bg-slate-100 text-slate-800 text-xs font-medium px-2.5 py-0.5 rounded border border-slate-200">
                              Processando
                            </span>
                        )}

                        {/* Individual Rename Button */}
                        {item.status === 'done' && (
                          <button
                            onClick={() => onSingleRename(item.id)}
                            className="flex items-center gap-1 text-[10px] text-brand-600 hover:text-brand-800 hover:underline"
                            title="Renomear apenas este arquivo"
                          >
                            <Play size={10} className="fill-current" /> Renomear Agora
                          </button>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      {item.metadata?.system_abbreviation && (
                        <span className="bg-blue-100 text-blue-800 text-xs font-medium px-2.5 py-0.5 rounded border border-blue-200">
                          {item.metadata?.system_abbreviation}
                        </span>
                      )}
                    </td>
                    <td className="px-6 py-4">
                         {item.metadata?.content_type_tag && (
                            <span className="border border-slate-200 text-slate-600 text-xs px-2 py-0.5 rounded bg-slate-50">
                                {item.metadata?.content_type_tag}
                            </span>
                         )}
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex flex-col gap-1">
                        <span className="text-xs font-bold text-slate-800">{item.metadata?.official_title}</span>
                        <p className="line-clamp-2 text-xs leading-relaxed text-slate-500" title={item.metadata?.summary}>
                            {item.metadata?.summary}
                        </p>
                         {/* Latest Log Message */}
                         {item.logs.length > 0 && (
                          <span className="text-[10px] text-slate-400 flex items-center gap-1 mt-1 truncate max-w-[200px]" title={item.logs[item.logs.length - 1].message}>
                             <FileClock size={10} /> 
                             {new Date(item.logs[item.logs.length - 1].timestamp).toLocaleTimeString()}: {item.logs[item.logs.length - 1].message}
                          </span>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { RpgMetadata } from "../types";

// Ensure API key is available
if (!process.env.API_KEY) {
  console.error("API_KEY is missing from environment variables.");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Sends a PDF base64 string to Gemini and requests structured RPG metadata.
 */
export const analyzeRpgPdf = async (base64Pdf: string, fileName: string): Promise<RpgMetadata> => {
  try {
    const modelId = 'gemini-2.0-flash-exp'; 

    const prompt = `
      Você é um Arquivista Sênior especializado em RPG de Mesa (Tabletop RPG). 
      Sua tarefa é analisar o arquivo PDF fornecido (Capa, Índice e conteúdo visual) e extrair metadados precisos para organização de arquivos digitais.

      Arquivo original: "${fileName}"

      DIRETRIZES DE ANÁLISE PARA NOMENCLATURA DE ARQUIVOS:

      A regra de ouro é: **{SISTEMA_EDICAO}_{TIPO}_{NOME_SLUG}.pdf**

      1. **Identificação do Sistema e Edição (system_abbreviation)**:
         - **IMPORTANTE:** Este campo deve identificar a "Database Original" ou Edição do sistema.
         - Deve ser sempre o PRIMEIRO elemento.
         - Diferencie edições claramente. Não use termos genéricos se puder ser específico.
         - Use siglas PADRONIZADAS (Máx 6 caracteres).
         - Exemplos de Mapeamento:
           - "Tormenta 20" -> "T20"
           - "Tormenta RPG (versão anterior)" -> "TRPG"
           - "Dungeons & Dragons 5th Edition" -> "DnD5e"
           - "Dungeons & Dragons 3.5" -> "DnD35"
           - "Old School Essentials" -> "OSE"
           - "Pathfinder 2nd Edition" -> "PF2e"
           - "Pathfinder 1st Edition" -> "PF1e"
           - "Vampire: The Masquerade 5th Edition" -> "V5"
           - "Vampire: The Masquerade 20th Anniversary" -> "V20"
           - "Call of Cthulhu 7th Edition" -> "CoC7"
           - Se não houver sistema claro -> "RPG"

      2. **Classificação de Tipo (content_type_tag)**:
         - Classifique o conteúdo em uma destas categorias estritas:
           - "Core" (Livro Básico, Livro do Jogador, Mestre)
           - "Sup" (Suplementos de regras, cenários, bestiários)
           - "Adv" (Aventuras, Campanhas, One-shots)
           - "Map" (Mapas, Battlegrids)
           - "Ficha" (Fichas de personagem)
           - "Zine" (Conteúdo indie curto)

      3. **Título Oficial (official_title)**:
         - O nome real do livro. Remova "PDF", "Scan", "Versão final" etc.

      4. **Slug para Arquivo (filename_slug)**:
         - Uma versão do Título Oficial formatada para nomes de arquivo.
         - Use Snake Case (palavras_separadas_por_underline).
         - Remova artigos desnecessários (o, a, um, do, da).
         - Ex: "O Atlas de Arton" -> "Atlas_de_Arton"
         - Ex: "Guia do Mestre" -> "Guia_do_Mestre"

      5. **Resumo (summary)**:
         - Um resumo de no máximo 200 caracteres focando no CONTEÚDO.

      Retorne APENAS o JSON.
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          { inlineData: { mimeType: 'application/pdf', data: base64Pdf } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            official_title: { type: Type.STRING },
            system_abbreviation: { type: Type.STRING },
            content_type_tag: { type: Type.STRING },
            summary: { type: Type.STRING },
            filename_slug: { type: Type.STRING },
            year: { type: Type.STRING },
          },
          required: ["official_title", "system_abbreviation", "content_type_tag", "summary", "filename_slug"]
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("A resposta da IA estava vazia.");
    }

    // CLEANUP: Gemini sometimes returns markdown code blocks ```json ... ```
    const cleanText = text.replace(/```json\s*/g, "").replace(/```\s*/g, "").trim();

    try {
      const data = JSON.parse(cleanText) as RpgMetadata;
      return data;
    } catch (parseError) {
      console.error("JSON Parse Failed. Raw text:", text);
      throw new Error("Falha ao processar a resposta JSON da IA.");
    }

  } catch (error: any) {
    console.error("Gemini API Error:", error);
    let errorMessage = "Erro ao analisar.";

    if (error.message) {
      if (error.message.includes("429")) {
        errorMessage = "Limite de requisições (429). Aguarde...";
      } else if (error.message.includes("404")) {
        errorMessage = "Modelo indisponível ou API Key inválida.";
      } else if (error.message.includes("SAFETY")) {
        errorMessage = "Conteúdo bloqueado por filtro de segurança.";
      }
    }
    throw new Error(errorMessage);
  }
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { BrainCircuit, Sparkles, Loader2, Plus, HardDrive, Upload, RefreshCw } from 'lucide-react';
import { AppState, LibraryEntry, FilterState, RegistryRecord, LogEntry } from './types';
import { fileToBase64 } from './utils/fileUtils';
import { renameFileOnDisk } from './utils/fileSystem';
import { analyzeRpgPdf } from './services/geminiService';
import { FileUpload } from './components/FileUpload';
import { Dashboard } from './components/Dashboard';

const App: React.FC = () => {
  const [library, setLibrary] = useState<LibraryEntry[]>([]);
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [isRenaming, setIsRenaming] = useState(false);

  // State for Resume/Import feature - Now holds full RegistryRecords
  const [registryDB, setRegistryDB] = useState<Map<string, RegistryRecord>>(new Map());
  const [importedCount, setImportedCount] = useState<number>(0);
  const importInputRef = useRef<HTMLInputElement>(null);

  const [filters, setFilters] = useState<FilterState>({
    system: 'Todos',
    type: 'Todos',
    search: ''
  });

  // --- Helper to Append Logs ---
  const addLog = (entry: LibraryEntry, action: LogEntry['action'], message: string): LibraryEntry => {
    return {
      ...entry,
      logs: [
        ...(entry.logs || []), 
        { timestamp: new Date().toISOString(), action, message }
      ]
    };
  };

  // --- File Processing Logic (AI Analysis) ---
  const processFile = useCallback(async (entry: LibraryEntry) => {
    // Skip if user manually overrode the name or if it's already done/renamed
    if (entry.isManualOverride || entry.status === 'renamed' || entry.status === 'done') return;

    try {
      const base64 = await fileToBase64(entry.file);
      const metadata = await analyzeRpgPdf(base64, entry.originalName);

      // Sanitize and Format
      const system = (metadata.system_abbreviation || "RPG").replace(/[^a-zA-Z0-9]/g, '');
      const type = (metadata.content_type_tag || "Doc").replace(/[^a-zA-Z0-9]/g, '');
      const slug = (metadata.filename_slug || "Unknown").replace(/[^a-zA-Z0-9_]/g, '');

      // Strict Naming Rule: SYSTEM(Edition)_TYPE_SLUG.pdf
      const newName = `${system}_${type}_${slug}.pdf`;

      setLibrary(prev => prev.map(item => {
        if (item.id === entry.id) {
          const updated = addLog(item, 'ANALYZE', `Metadados gerados: ${metadata.official_title} (${metadata.system_abbreviation})`);
          return { ...updated, status: 'done', metadata, suggestedName: newName };
        }
        return item;
      }));

    } catch (error: any) {
      console.error(`Error processing ${entry.originalName}:`, error);
      setLibrary(prev => prev.map(item => {
        if (item.id === entry.id) {
          const updated = addLog(item, 'ERROR', error.message || "Erro na análise");
          return { ...updated, status: 'error', error: error.message };
        }
        return item;
      }));
    } finally {
      setProcessingQueue(prev => prev.filter(id => id !== entry.id));
    }
  }, []);

  // --- Queue Management (Concurrency optimized to 3) ---
  useEffect(() => {
    const CONCURRENCY_LIMIT = 3;
    const processingCount = library.filter(item => item.status === 'analyzing').length;

    if (processingCount < CONCURRENCY_LIMIT) {
      const nextItems = library
        .filter(item => item.status === 'pending' && !processingQueue.includes(item.id))
        .slice(0, CONCURRENCY_LIMIT - processingCount);

      if (nextItems.length > 0) {
        const nextIds = nextItems.map(i => i.id);
        setProcessingQueue(prev => [...prev, ...nextIds]);

        // Mark as analyzing immediately to prevent double selection in next render
        setLibrary(prev => prev.map(i => nextIds.includes(i.id) ? { ...i, status: 'analyzing' } : i));

        // Trigger process
        nextItems.forEach(item => processFile(item));
      }
    }
  }, [library, processingQueue, processFile]);

  // --- Actions: Rename, Manual Edit, Retry, Reset ---

  const handleManualEdit = (id: string, newName: string) => {
    setLibrary(prev => prev.map(item => {
      if (item.id === id) {
        // Log the manual change
        const updated = addLog(item, 'EDIT', `Nome editado manualmente de '${item.suggestedName}' para '${newName}'`);
        return {
          ...updated,
          suggestedName: newName,
          isManualOverride: true,
          status: 'done' // Ensure it's ready for renaming
        };
      }
      return item;
    }));
  };

  const handleSingleRename = async (id: string) => {
    const item = library.find(i => i.id === id);
    if (!item || !item.handle) {
      alert("Arquivo não acessível para escrita.");
      return;
    }

    try {
      await renameFileOnDisk(item);
      setLibrary(prev => prev.map(i => {
        if (i.id === id) {
          const updated = addLog(i, 'RENAME', `Renomeado individualmente para ${i.suggestedName}`);
          return { ...updated, status: 'renamed' };
        }
        return i;
      }));
    } catch (e: any) {
      console.error(`Erro ao renomear ${item.originalName}:`, e);
      alert(`Erro: ${e.message}`);
      setLibrary(prev => prev.map(i => {
        if (i.id === id) return addLog(i, 'ERROR', `Falha ao renomear: ${e.message}`);
        return i;
      }));
    }
  };

  const handleRenameBatch = async () => {
    const canRename = library.some(i => i.handle !== null);

    if (!canRename) {
      alert("⚠️ Modo de Leitura Apenas\n\nO acesso de escrita ao disco está bloqueado.");
      return;
    }

    const toRename = library.filter(i => i.status === 'done' && i.suggestedName !== i.originalName);
    if (toRename.length === 0) return;

    if (!window.confirm(`Isso renomeará ${toRename.length} arquivos permanentemente. Deseja continuar?`)) return;

    setIsRenaming(true);

    for (const item of toRename) {
      try {
        await renameFileOnDisk(item);

        setLibrary(prev => prev.map(i => {
           if (i.id === item.id) {
             const updated = addLog(i, 'RENAME', `Renomeado em lote para ${i.suggestedName}`);
             return { ...updated, status: 'renamed' };
           }
           return i;
        }));

      } catch (e: any) {
        console.error(`Falha ao renomear ${item.originalName}:`, e);
        setLibrary(prev => prev.map(i => {
           if (i.id === item.id) {
             return addLog(i, 'ERROR', `Falha ao renomear: ${e.message}`);
           }
           return i;
        }));
      }
    }
    setIsRenaming(false);
  };

  const handleRetryErrors = () => {
    setLibrary(prev => prev.map(item => 
      item.status === 'error' 
        ? { ...item, status: 'pending', error: undefined, logs: [...item.logs, { timestamp: new Date().toISOString(), action: 'RESTORE', message: 'Tentativa de reprocessamento.'}] } 
        : item
    ));
  };

  const handleReset = () => {
    if (!window.confirm("Isso limpará toda a lista atual. Deseja continuar?")) return;
    setLibrary([]);
    setProcessingQueue([]);
    setRegistryDB(new Map());
    setImportedCount(0);
    setAppState(AppState.IDLE);
    setFilters({ system: 'Todos', type: 'Todos', search: '' });
  };

  // --- Resume / Import Logic ---
  const handleImportJSON = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (Array.isArray(json)) {
          // Build the Registry Map using Fingerprint as Key
          const newRegistry = new Map<string, RegistryRecord>();
          json.forEach((record: RegistryRecord) => {
             if (record.fingerprint) {
                newRegistry.set(record.fingerprint, record);
             }
          });

          setRegistryDB(newRegistry);
          setImportedCount(newRegistry.size);
        } else {
          alert("Banco de dados JSON inválido.");
        }
      } catch (err) {
        console.error(err);
        alert("Erro ao ler o arquivo JSON.");
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleEntriesLoaded = (freshEntries: LibraryEntry[]) => {
    // Create an auxiliary index for lookup by Current Name
    const dbByFilename = new Map<string, RegistryRecord>();
    registryDB.forEach(record => {
      if (record.currentName) {
        dbByFilename.set(record.currentName, record);
      }
    });

    const mergedEntries = freshEntries.map(entry => {
        // PRIORITY 1: Exact Fingerprint Match
        const fpRecord = registryDB.get(entry.fingerprint);
        if (fpRecord) {
            return {
              ...entry,
              status: fpRecord.status === 'renamed' ? 'renamed' : 'done',
              metadata: fpRecord.metadata,
              suggestedName: fpRecord.currentName,
              isManualOverride: fpRecord.isManualOverride,
              logs: [...(fpRecord.logs || []), { timestamp: new Date().toISOString(), action: 'RESTORE', message: 'Registro recuperado (Fingerprint).' }]
            } as LibraryEntry;
        }

        // PRIORITY 2: Filename Match
        const nameRecord = dbByFilename.get(entry.originalName);
        if (nameRecord) {
           return {
             ...entry,
             status: 'renamed', 
             metadata: nameRecord.metadata,
             suggestedName: nameRecord.currentName,
             isManualOverride: nameRecord.isManualOverride,
             logs: [...(nameRecord.logs || []), { timestamp: new Date().toISOString(), action: 'RESTORE', message: 'Registro recuperado (Nome de Arquivo).' }]
           } as LibraryEntry;
        }

        // New File
        return entry;
    });

    setLibrary(prev => [...prev, ...mergedEntries]);
    setAppState(AppState.DASHBOARD);
  };

  // --- Render Helpers ---

  const processingCount = library.filter(i => i.status === 'pending' || i.status === 'analyzing').length;
  const progressPercent = library.length > 0 
    ? ((library.length - processingCount) / library.length) * 100 
    : 0;

  return (
    <div className="flex flex-col h-screen bg-slate-50">

      <input 
        type="file" 
        accept=".json" 
        ref={importInputRef} 
        className="hidden" 
        onChange={handleImportJSON} 
      />

      {/* Header */}
      <nav className="w-full px-6 py-3 flex items-center justify-between border-b border-slate-200 bg-white z-50 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="bg-brand-600 p-2 rounded-lg">
            <BrainCircuit className="text-white w-6 h-6" />
          </div>
          <div className="flex flex-col">
            <span className="text-lg font-bold text-slate-800 leading-tight">
              T20 RPG Indexer
            </span>
            <span className="text-xs text-slate-500">Local File System Edition</span>
          </div>
        </div>

        <div className="flex items-center gap-4">
           {processingCount > 0 && (
             <div className="flex items-center gap-3 bg-brand-50 px-3 py-1.5 rounded-full border border-brand-100">
               <Loader2 className="w-4 h-4 text-brand-600 animate-spin" />
               <div className="flex flex-col min-w-[120px]">
                 <span className="text-xs font-semibold text-brand-700">Indexando... {library.length - processingCount}/{library.length}</span>
                 <div className="w-full bg-brand-200 rounded-full h-1 mt-1">
                   <div className="bg-brand-500 h-1 rounded-full transition-all duration-300" style={{ width: `${progressPercent}%` }}></div>
                 </div>
               </div>
             </div>
           )}
           <div className="hidden sm:flex items-center gap-2 text-xs text-slate-500 bg-slate-100 px-3 py-1 rounded-md">
            <Sparkles size={12} className="text-brand-500" />
            <span>Gemini 2.0 Flash</span>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden p-6 max-w-[1600px] w-full mx-auto">

        {appState === AppState.IDLE ? (
          <div className="h-full flex flex-col items-center justify-center animate-fade-in-up">
            <div className="text-center space-y-6 max-w-2xl">
              <h1 className="text-4xl font-extrabold text-slate-900">
                Organize seu acervo local <br/>
                <span className="text-brand-600">direto no navegador.</span>
              </h1>

              {importedCount === 0 ? (
                 <>
                    <p className="text-lg text-slate-600">
                      Selecione uma pasta raiz. A IA analisará recursivamente, gerará metadados e criará um registro histórico permanente.
                    </p>
                    <div className="bg-yellow-50 border border-yellow-200 p-4 rounded-lg text-sm text-yellow-800 text-left mx-auto max-w-lg">
                      <strong>Nota Importante:</strong> A renomeação automática de arquivos requer um navegador compatível com a API de Sistema de Arquivos (Chrome/Edge em Desktop).
                    </div>
                 </>
              ) : (
                 <div className="bg-green-50 border border-green-200 p-6 rounded-xl animate-fade-in text-left mx-auto max-w-xl shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                      <div className="p-2 bg-green-100 rounded-full text-green-600">
                        <RefreshCw size={24} />
                      </div>
                      <h3 className="text-lg font-bold text-green-800">Database Carregado!</h3>
                    </div>
                    <p className="text-green-700 mb-4">
                      {importedCount} registros históricos identificados.
                    </p>
                    <p className="text-slate-600 text-sm mb-4">
                      Selecione a pasta raiz novamente. O sistema irá comparar os arquivos físicos com o banco de dados e ignorar os já processados ou renomeados.
                    </p>
                 </div>
              )}

              <div className="pt-4 w-full max-w-xl mx-auto space-y-4">
                <FileUpload onEntriesLoaded={handleEntriesLoaded} />

                {importedCount === 0 && (
                  <button 
                    onClick={() => importInputRef.current?.click()}
                    className="flex items-center justify-center gap-2 w-full py-3 text-slate-500 hover:text-brand-600 hover:bg-slate-100 rounded-lg transition-colors text-sm font-medium border border-transparent hover:border-slate-200"
                  >
                    <Upload size={16} />
                    Carregar Database (.json)
                  </button>
                )}
              </div>
            </div>
          </div>
        ) : (
          <Dashboard 
            library={library} 
            filters={filters} 
            setFilters={setFilters} 
            onRenameClick={handleRenameBatch}
            onRetryClick={handleRetryErrors}
            onResetClick={handleReset}
            onManualEdit={handleManualEdit}
            onSingleRename={handleSingleRename}
            isRenaming={isRenaming}
          />
        )}

      </main>
    </div>
  );
};

export default App;

export enum AppState {
  IDLE = 'IDLE',
  PROCESSING = 'PROCESSING',
  DASHBOARD = 'DASHBOARD',
  ERROR = 'ERROR'
}

export interface RpgMetadata {
  official_title: string;
  magazine_edition: string; // New: Number of the Dragão Brasil issue (e.g., "110")
  magazine_section: string; // New: Fixed column name (e.g., "Chefe de Fase", "Caverna do Saber")
  summary: string;
  filename_slug: string;
}

export interface LogEntry {
  timestamp: string;
  action: 'SCAN' | 'ANALYZE' | 'RENAME' | 'ERROR' | 'RESTORE' | 'EDIT';
  message: string;
}

// Interface for Native File System Handle
export interface FileSystemFileHandle extends FileSystemHandle {
  getFile: () => Promise<File>;
  move: (newName: string) => Promise<void>;
}

export interface FileSystemDirectoryHandle extends FileSystemHandle {
  values: () => AsyncIterableIterator<FileSystemHandle>;
  getDirectoryHandle: (name: string) => Promise<FileSystemDirectoryHandle>;
  getFileHandle: (name: string) => Promise<FileSystemFileHandle>;
}

export interface LibraryEntry {
  id: string; // Temporary UI ID
  fingerprint: string; // Unique ID based on File Content Metadata (Size + Date + Path)
  handle: FileSystemFileHandle | null;
  file: File;

  // File System Stats
  originalName: string;
  relativePath: string;
  size: number;
  lastModified: number;

  // Processing State
  suggestedName: string;
  isManualOverride?: boolean; // New: Tracks if user manually changed the name
  metadata: RpgMetadata | null;
  status: 'pending' | 'analyzing' | 'done' | 'renamed' | 'error' | 'skipped';
  error?: string;

  // History
  logs: LogEntry[];
}

// The Persistent Database Record
export interface RegistryRecord {
  fingerprint: string;
  originalPath: string;
  currentName: string;
  fileSize: number;
  lastModified: number;
  metadata: RpgMetadata | null;
  status: string;
  isManualOverride?: boolean;
  logs: LogEntry[];
  lastUpdated: string;
}

export interface FilterState {
  section: string;
  search: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { RpgMetadata } from "../types";

// Ensure API key is available
if (!process.env.API_KEY) {
  console.error("API_KEY is missing from environment variables.");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Sends a PDF base64 string to Gemini and requests structured metadata specialized for Dragão Brasil magazine.
 */
export const analyzeRpgPdf = async (base64Pdf: string, fileName: string): Promise<RpgMetadata> => {
  try {
    const modelId = 'gemini-2.0-flash-exp'; 

    const prompt = `
      Você é o Arquivista Oficial da **Revista Dragão Brasil** (DB).
      Sua tarefa é analisar o arquivo PDF fornecido (que contém uma matéria ou edição completa) e extrair metadados para catalogação.

      Arquivo original: "${fileName}"

      DIRETRIZES ESTRITAS DE EXTRAÇÃO:

      1. **Número da Edição (magazine_edition)**:
         - Identifique o número da revista Dragão Brasil.
         - Procure por "Dragão Brasil #XX", "DB XX", ou no rodapé/cabeçalho das páginas.
         - Retorne APENAS o número (ex: "10", "123", "01"). 
         - Se for impossível determinar, use "000".

      2. **Seção / Coluna Fixa (magazine_section)**:
         - Identifique a qual seção fixa da revista esta matéria pertence.
         - Exemplos comuns:
           - "Notícias do Bardo"
           - "Pergaminhos dos Leitores"
           - "Dicas de Mestre"
           - "Chefe de Fase" (Adaptações de games/animes)
           - "Caverna do Saber" (Regras e tutoriais)
           - "Lendas Lendárias"
           - "Gazeta do Reinado"
           - "Resenha" ou "Reviews"
           - "Aventura" (Se for uma aventura completa)
           - "Toolbox"
           - "Quadrinhos" ou "Manga"
           - "Capa" (Se for a matéria principal)
         - Se não tiver nome de seção claro, use "Artigo".

      3. **Título da Matéria (official_title)**:
         - O título principal do conteúdo.
         - Ex: "Adaptação de Street Fighter", "A Maldição de Strahd", "Novos Talentos para Tormenta".

      4. **Slug para Arquivo (filename_slug)**:
         - Crie um slug baseado no Título Oficial e na Seção (se relevante).
         - Use Snake Case (palavras_separadas_por_underline).
         - Remova artigos (o, a, de, da).
         - Ex: "Adaptacao_Street_Fighter", "Novos_Talentos_T20".

      5. **Resumo (summary)**:
         - Resumo curto do conteúdo (máx 150 caracteres).

      Retorne APENAS o JSON.
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          { inlineData: { mimeType: 'application/pdf', data: base64Pdf } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            official_title: { type: Type.STRING },
            magazine_edition: { type: Type.STRING },
            magazine_section: { type: Type.STRING },
            summary: { type: Type.STRING },
            filename_slug: { type: Type.STRING },
          },
          required: ["official_title", "magazine_edition", "magazine_section", "summary", "filename_slug"]
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("A resposta da IA estava vazia.");
    }

    // CLEANUP: Gemini sometimes returns markdown code blocks ```json ... ```
    const cleanText = text.replace(/```json\s*/g, "").replace(/```\s*/g, "").trim();

    try {
      const data = JSON.parse(cleanText) as RpgMetadata;
      return data;
    } catch (parseError) {
      console.error("JSON Parse Failed. Raw text:", text);
      throw new Error("Falha ao processar a resposta JSON da IA.");
    }

  } catch (error: any) {
    console.error("Gemini API Error:", error);
    let errorMessage = "Erro ao analisar.";

    if (error.message) {
      if (error.message.includes("429")) {
        errorMessage = "Limite de requisições (429). Aguarde...";
      } else if (error.message.includes("404")) {
        errorMessage = "Modelo indisponível ou API Key inválida.";
      } else if (error.message.includes("SAFETY")) {
        errorMessage = "Conteúdo bloqueado por filtro de segurança.";
      }
    }
    throw new Error(errorMessage);
  }
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { BrainCircuit, Sparkles, Loader2, Plus, HardDrive, Upload, RefreshCw } from 'lucide-react';
import { AppState, LibraryEntry, FilterState, RegistryRecord, LogEntry } from './types';
import { fileToBase64 } from './utils/fileUtils';
import { renameFileOnDisk } from './utils/fileSystem';
import { analyzeRpgPdf } from './services/geminiService';
import { FileUpload } from './components/FileUpload';
import { Dashboard } from './components/Dashboard';

const App: React.FC = () => {
  const [library, setLibrary] = useState<LibraryEntry[]>([]);
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [isRenaming, setIsRenaming] = useState(false);

  // State for Resume/Import feature
  const [registryDB, setRegistryDB] = useState<Map<string, RegistryRecord>>(new Map());
  const [importedCount, setImportedCount] = useState<number>(0);
  const importInputRef = useRef<HTMLInputElement>(null);

  const [filters, setFilters] = useState<FilterState>({
    section: 'Todas',
    search: ''
  });

  // --- Helper to Append Logs ---
  const addLog = (entry: LibraryEntry, action: LogEntry['action'], message: string): LibraryEntry => {
    return {
      ...entry,
      logs: [
        ...(entry.logs || []), 
        { timestamp: new Date().toISOString(), action, message }
      ]
    };
  };

  // --- File Processing Logic (AI Analysis) ---
  const processFile = useCallback(async (entry: LibraryEntry) => {
    if (entry.isManualOverride || entry.status === 'renamed' || entry.status === 'done') return;

    try {
      const base64 = await fileToBase64(entry.file);
      const metadata = await analyzeRpgPdf(base64, entry.originalName);

      // Extract and Pad Edition Number (e.g., "1" -> "001")
      const editionRaw = (metadata.magazine_edition || "000").replace(/\D/g, '');
      const edition = editionRaw.padStart(3, '0');

      const slug = (metadata.filename_slug || "Unknown").replace(/[^a-zA-Z0-9_]/g, '');

      // Strict Naming Rule: DB_{Edition}_{Slug}.pdf
      const newName = `DB_${edition}_${slug}.pdf`;

      setLibrary(prev => prev.map(item => {
        if (item.id === entry.id) {
          const updated = addLog(item, 'ANALYZE', `DB ${edition} - ${metadata.magazine_section}: ${metadata.official_title}`);
          return { ...updated, status: 'done', metadata, suggestedName: newName };
        }
        return item;
      }));

    } catch (error: any) {
      console.error(`Error processing ${entry.originalName}:`, error);
      setLibrary(prev => prev.map(item => {
        if (item.id === entry.id) {
          const updated = addLog(item, 'ERROR', error.message || "Erro na análise");
          return { ...updated, status: 'error', error: error.message };
        }
        return item;
      }));
    } finally {
      setProcessingQueue(prev => prev.filter(id => id !== entry.id));
    }
  }, []);

  // --- Queue Management (Concurrency optimized to 3) ---
  useEffect(() => {
    const CONCURRENCY_LIMIT = 3;
    const processingCount = library.filter(item => item.status === 'analyzing').length;

    if (processingCount < CONCURRENCY_LIMIT) {
      const nextItems = library
        .filter(item => item.status === 'pending' && !processingQueue.includes(item.id))
        .slice(0, CONCURRENCY_LIMIT - processingCount);

      if (nextItems.length > 0) {
        const nextIds = nextItems.map(i => i.id);
        setProcessingQueue(prev => [...prev, ...nextIds]);

        // Mark as analyzing immediately to prevent double selection in next render
        setLibrary(prev => prev.map(i => nextIds.includes(i.id) ? { ...i, status: 'analyzing' } : i));

        // Trigger process
        nextItems.forEach(item => processFile(item));
      }
    }
  }, [library, processingQueue, processFile]);

  // --- Actions: Rename, Manual Edit, Retry, Reset ---

  const handleManualEdit = (id: string, newName: string) => {
    setLibrary(prev => prev.map(item => {
      if (item.id === id) {
        const updated = addLog(item, 'EDIT', `Nome editado manualmente de '${item.suggestedName}' para '${newName}'`);
        return {
          ...updated,
          suggestedName: newName,
          isManualOverride: true,
          status: 'done' 
        };
      }
      return item;
    }));
  };

  const handleSingleRename = async (id: string) => {
    const item = library.find(i => i.id === id);
    if (!item || !item.handle) {
      alert("Arquivo não acessível para escrita.");
      return;
    }

    try {
      await renameFileOnDisk(item);
      setLibrary(prev => prev.map(i => {
        if (i.id === id) {
          const updated = addLog(i, 'RENAME', `Renomeado individualmente para ${i.suggestedName}`);
          return { ...updated, status: 'renamed' };
        }
        return i;
      }));
    } catch (e: any) {
      console.error(`Erro ao renomear ${item.originalName}:`, e);
      alert(`Erro: ${e.message}`);
      setLibrary(prev => prev.map(i => {
        if (i.id === id) return addLog(i, 'ERROR', `Falha ao renomear: ${e.message}`);
        return i;
      }));
    }
  };

  const handleRenameBatch = async () => {
    const canRename = library.some(i => i.handle !== null);

    if (!canRename) {
      alert("⚠️ Modo de Leitura Apenas\n\nO acesso de escrita ao disco está bloqueado.");
      return;
    }

    const toRename = library.filter(i => i.status === 'done' && i.suggestedName !== i.originalName);
    if (toRename.length === 0) return;

    if (!window.confirm(`Isso renomeará ${toRename.length} arquivos permanentemente. Deseja continuar?`)) return;

    setIsRenaming(true);

    for (const item of toRename) {
      try {
        await renameFileOnDisk(item);

        setLibrary(prev => prev.map(i => {
           if (i.id === item.id) {
             const updated = addLog(i, 'RENAME', `Renomeado em lote para ${i.suggestedName}`);
             return { ...updated, status: 'renamed' };
           }
           return i;
        }));

      } catch (e: any) {
        console.error(`Falha ao renomear ${item.originalName}:`, e);
        setLibrary(prev => prev.map(i => {
           if (i.id === item.id) {
             return addLog(i, 'ERROR', `Falha ao renomear: ${e.message}`);
           }
           return i;
        }));
      }
    }
    setIsRenaming(false);
  };

  const handleRetryErrors = () => {
    setLibrary(prev => prev.map(item => 
      item.status === 'error' 
        ? { ...item, status: 'pending', error: undefined, logs: [...item.logs, { timestamp: new Date().toISOString(), action: 'RESTORE', message: 'Tentativa de reprocessamento.'}] } 
        : item
    ));
  };

  const handleReset = () => {
    if (!window.confirm("Isso limpará toda a lista atual. Deseja continuar?")) return;
    setLibrary([]);
    setProcessingQueue([]);
    setRegistryDB(new Map());
    setImportedCount(0);
    setAppState(AppState.IDLE);
    setFilters({ section: 'Todas', search: '' });
  };

  // --- Resume / Import Logic ---
  const handleImportJSON = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (Array.isArray(json)) {
          const newRegistry = new Map<string, RegistryRecord>();
          json.forEach((record: RegistryRecord) => {
             if (record.fingerprint) {
                newRegistry.set(record.fingerprint, record);
             }
          });
          setRegistryDB(newRegistry);
          setImportedCount(newRegistry.size);
        } else {
          alert("Banco de dados JSON inválido.");
        }
      } catch (err) {
        console.error(err);
        alert("Erro ao ler o arquivo JSON.");
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleEntriesLoaded = (freshEntries: LibraryEntry[]) => {
    const dbByFilename = new Map<string, RegistryRecord>();
    registryDB.forEach(record => {
      if (record.currentName) {
        dbByFilename.set(record.currentName, record);
      }
    });

    const mergedEntries = freshEntries.map(entry => {
        // PRIORITY 1: Exact Fingerprint Match
        const fpRecord = registryDB.get(entry.fingerprint);
        if (fpRecord) {
            return {
              ...entry,
              status: fpRecord.status === 'renamed' ? 'renamed' : 'done',
              metadata: fpRecord.metadata,
              suggestedName: fpRecord.currentName,
              isManualOverride: fpRecord.isManualOverride,
              logs: [...(fpRecord.logs || []), { timestamp: new Date().toISOString(), action: 'RESTORE', message: 'Registro recuperado (Fingerprint).' }]
            } as LibraryEntry;
        }

        // PRIORITY 2: Filename Match
        const nameRecord = dbByFilename.get(entry.originalName);
        if (nameRecord) {
           return {
             ...entry,
             status: 'renamed', 
             metadata: nameRecord.metadata,
             suggestedName: nameRecord.currentName,
             isManualOverride: nameRecord.isManualOverride,
             logs: [...(nameRecord.logs || []), { timestamp: new Date().toISOString(), action: 'RESTORE', message: 'Registro recuperado (Nome de Arquivo).' }]
           } as LibraryEntry;
        }

        // New File
        return entry;
    });

    setLibrary(prev => [...prev, ...mergedEntries]);
    setAppState(AppState.DASHBOARD);
  };

  // --- Render Helpers ---

  const processingCount = library.filter(i => i.status === 'pending' || i.status === 'analyzing').length;
  const progressPercent = library.length > 0 
    ? ((library.length - processingCount) / library.length) * 100 
    : 0;

  return (
    <div className="flex flex-col h-screen bg-slate-50">

      <input 
        type="file" 
        accept=".json" 
        ref={importInputRef} 
        className="hidden" 
        onChange={handleImportJSON} 
      />

      {/* Header */}
      <nav className="w-full px-6 py-3 flex items-center justify-between border-b border-slate-200 bg-white z-50 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="bg-red-700 p-2 rounded-lg">
            <BrainCircuit className="text-white w-6 h-6" />
          </div>
          <div className="flex flex-col">
            <span className="text-lg font-bold text-slate-800 leading-tight">
              Dragão Brasil Indexer
            </span>
            <span className="text-xs text-slate-500">AI Edition</span>
          </div>
        </div>

        <div className="flex items-center gap-4">
           {processingCount > 0 && (
             <div className="flex items-center gap-3 bg-brand-50 px-3 py-1.5 rounded-full border border-brand-100">
               <Loader2 className="w-4 h-4 text-brand-600 animate-spin" />
               <div className="flex flex-col min-w-[120px]">
                 <span className="text-xs font-semibold text-brand-700">Indexando... {library.length - processingCount}/{library.length}</span>
                 <div className="w-full bg-brand-200 rounded-full h-1 mt-1">
                   <div className="bg-brand-500 h-1 rounded-full transition-all duration-300" style={{ width: `${progressPercent}%` }}></div>
                 </div>
               </div>
             </div>
           )}
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden p-6 max-w-[1600px] w-full mx-auto">

        {appState === AppState.IDLE ? (
          <div className="h-full flex flex-col items-center justify-center animate-fade-in-up">
            <div className="text-center space-y-6 max-w-2xl">
              <h1 className="text-4xl font-extrabold text-slate-900">
                Organize sua coleção da <br/>
                <span className="text-red-700">Dragão Brasil.</span>
              </h1>

              {importedCount === 0 ? (
                 <>
                    <p className="text-lg text-slate-600">
                      Selecione a pasta onde estão seus PDFs da revista. A IA identificará a edição e a coluna automaticamente.
                    </p>
                    <div className="bg-yellow-50 border border-yellow-200 p-4 rounded-lg text-sm text-yellow-800 text-left mx-auto max-w-lg">
                      <strong>Nota:</strong> A renomeação automática (DB_000_Slug.pdf) requer suporte a API de Sistema de Arquivos (Chrome/Edge).
                    </div>
                 </>
              ) : (
                 <div className="bg-green-50 border border-green-200 p-6 rounded-xl animate-fade-in text-left mx-auto max-w-xl shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                      <div className="p-2 bg-green-100 rounded-full text-green-600">
                        <RefreshCw size={24} />
                      </div>
                      <h3 className="text-lg font-bold text-green-800">Database Carregado!</h3>
                    </div>
                    <p className="text-green-700 mb-4">
                      {importedCount} registros históricos identificados.
                    </p>
                 </div>
              )}

              <div className="pt-4 w-full max-w-xl mx-auto space-y-4">
                <FileUpload onEntriesLoaded={handleEntriesLoaded} />

                {importedCount === 0 && (
                  <button 
                    onClick={() => importInputRef.current?.click()}
                    className="flex items-center justify-center gap-2 w-full py-3 text-slate-500 hover:text-brand-600 hover:bg-slate-100 rounded-lg transition-colors text-sm font-medium border border-transparent hover:border-slate-200"
                  >
                    <Upload size={16} />
                    Carregar Database (.json)
                  </button>
                )}
              </div>
            </div>
          </div>
        ) : (
          <Dashboard 
            library={library} 
            filters={filters} 
            setFilters={setFilters} 
            onRenameClick={handleRenameBatch}
            onRetryClick={handleRetryErrors}
            onResetClick={handleReset}
            onManualEdit={handleManualEdit}
            onSingleRename={handleSingleRename}
            isRenaming={isRenaming}
          />
        )}

      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState } from 'react';
import { LibraryEntry, FilterState, RegistryRecord } from '../types';
import { Search, Filter, BookOpen, Sword, Scroll, Download, CheckCircle, Save, FolderInput, RefreshCw, Trash2, AlertTriangle, FileClock, Pencil, X, Play, UserCheck, LayoutTemplate } from 'lucide-react';

interface DashboardProps {
  library: LibraryEntry[];
  filters: FilterState;
  setFilters: React.Dispatch<React.SetStateAction<FilterState>>;
  onRenameClick: () => void;
  onRetryClick: () => void;
  onResetClick: () => void;
  onManualEdit: (id: string, newName: string) => void;
  onSingleRename: (id: string) => void;
  isRenaming: boolean;
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  library, filters, setFilters, onRenameClick, onRetryClick, onResetClick, onManualEdit, onSingleRename, isRenaming 
}) => {

  // State for inline editing
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState<string>("");

  // Calculate Metrics
  const metrics = useMemo(() => {
    const doneItems = library.filter(i => (i.status === 'done' || i.status === 'renamed' || i.status === 'skipped') && i.metadata);
    // Unique Editions
    const editions = new Set(doneItems.map(i => i.metadata?.magazine_edition));
    // Count of 'Chefe de Fase' (popular section)
    const chefes = doneItems.filter(i => i.metadata?.magazine_section?.toLowerCase().includes('chefe'));
    const renamed = library.filter(i => i.status === 'renamed').length;
    const errors = library.filter(i => i.status === 'error').length;

    return {
      total: doneItems.length,
      editions: editions.size,
      chefes: chefes.length,
      renamed,
      errors
    };
  }, [library]);

  const availableSections = useMemo(() => {
    const sections = new Set(library.map(i => i.metadata?.magazine_section).filter(Boolean));
    return ["Todas", ...Array.from(sections).sort()];
  }, [library]);

  const filteredLibrary = useMemo(() => {
    return library.filter(item => {
      // Allow viewing errors if searching
      if (item.status === 'pending') return false; 

      const matchesSection = filters.section === "Todas" || item.metadata?.magazine_section === filters.section;
      const searchLower = filters.search.toLowerCase();

      const summary = item.metadata?.summary?.toLowerCase() || "";
      const title = item.metadata?.official_title?.toLowerCase() || "";
      const edition = item.metadata?.magazine_edition || "";

      const matchesSearch = !filters.search || 
        item.suggestedName.toLowerCase().includes(searchLower) ||
        item.originalName.toLowerCase().includes(searchLower) ||
        title.includes(searchLower) ||
        summary.includes(searchLower) ||
        edition.includes(searchLower);

      return matchesSection && matchesSearch;
    });
  }, [library, filters]);

  const handleExport = () => {
    // Export strict RegistryRecord format
    const dbExport: RegistryRecord[] = library.map(l => ({
        fingerprint: l.fingerprint,
        originalPath: l.relativePath,
        currentName: l.suggestedName,
        fileSize: l.size,
        lastModified: l.lastModified,
        metadata: l.metadata,
        status: l.status,
        isManualOverride: l.isManualOverride,
        logs: l.logs,
        lastUpdated: new Date().toISOString()
    }));

    const dataStr = JSON.stringify(dbExport, null, 2);

    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `dragao_brasil_index_${new Date().toISOString().slice(0,10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  const startEditing = (item: LibraryEntry) => {
    setEditingId(item.id);
    setEditValue(item.suggestedName);
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditValue("");
  };

  const saveEditing = (id: string) => {
    if (editValue.trim()) {
      onManualEdit(id, editValue.trim());
    }
    setEditingId(null);
    setEditValue("");
  };

  const pendingRenames = library.filter(i => i.status === 'done').length;

  return (
    <div className="flex flex-col h-full gap-6">

      {/* Header Actions */}
