import { LibraryEntry, FileSystemDirectoryHandle, FileSystemFileHandle, FileSystemHandle } from '../types';

/**
 * Helper to generate a unique fingerprint for a file without reading its content.
 * Combines Relative Path + Size + LastModified.
 */
const generateFingerprint = (relativePath: string, file: File): string => {
  return `${relativePath}::${file.size}::${file.lastModified}`;
};

/**
 * Creates a LibraryEntry from a FileSystemFileHandle and File object.
 */
const createEntry = (file: File, handle: FileSystemFileHandle | null, path: string): LibraryEntry => {
  return {
    id: crypto.randomUUID(),
    fingerprint: generateFingerprint(path, file),
    handle: handle,
    file: file,
    originalName: file.name,
    relativePath: path,
    size: file.size,
    lastModified: file.lastModified,
    suggestedName: 'Aguardando análise...',
    metadata: null,
    status: 'pending',
    logs: [{
      timestamp: new Date().toISOString(),
      action: 'SCAN',
      message: handle ? 'Arquivo detectado (Acesso de Escrita OK).' : 'Arquivo detectado (Modo Leitura).'
    }]
  };
};

/**
 * Recursively processes a FileSystemHandle (can be file or directory).
 */
export async function processHandle(
  handle: FileSystemHandle,
  path = ''
): Promise<LibraryEntry[]> {
  const entries: LibraryEntry[] = [];

  if (handle.kind === 'file') {
    const fileHandle = handle as FileSystemFileHandle;
    if (fileHandle.name.toLowerCase().endsWith('.pdf')) {
      const file = await fileHandle.getFile();
      const relativePath = path + file.name;
      entries.push(createEntry(file, fileHandle, relativePath));
    }
  } else if (handle.kind === 'directory') {
    const dirHandle = handle as FileSystemDirectoryHandle;
    const newPath = path ? `${path}${dirHandle.name}/` : ''; // Don't add slash if it's the root being processed

    // @ts-ignore - TS sometimes complains about async iterator on handle
    for await (const entry of dirHandle.values()) {
      const subEntries = await processHandle(entry, newPath);
      entries.push(...subEntries);
    }
  }

  return entries;
}

/**
 * Wrapper to process standard File objects (fallback input).
 */
export function processFileList(fileList: FileList): LibraryEntry[] {
  const entries: LibraryEntry[] = [];
  Array.from(fileList).forEach(file => {
    if (file.name.toLowerCase().endsWith('.pdf')) {
      const relativePath = file.webkitRelativePath || file.name;
      entries.push(createEntry(file, null, relativePath));
    }
  });
  return entries;
}

/**
 * Renames a file on the user's disk using the File System Access API.
 */
export async function renameFileOnDisk(entry: LibraryEntry): Promise<void> {
  if (!entry.handle) {
    throw new Error("Modo de compatibilidade: O acesso direto ao disco não está disponível.");
  }

  if (!entry.suggestedName) {
    throw new Error("Nome sugerido ausente.");
  }

  // Feature detection for .move() (Chromium based browsers)
  // @ts-ignore
  if (typeof entry.handle.move === 'function') {
     // @ts-ignore
     await entry.handle.move(entry.suggestedName);
  } else {
    throw new Error("Seu navegador não suporta a função 'move' nativa (API experimental). Tente usar Chrome ou Edge atualizados.");
  }
}

/**
 * Generates a Windows Batch script content to rename files.
 */
export function generateRenameBat(entries: LibraryEntry[]): string {
    const lines = [
      '@echo off', 
      'chcp 65001 > nul', 
      'echo ==========================================',
      'echo      Renomeando Arquivos (Dragao Brasil)',
      'echo ==========================================',
      'echo.'
    ];

    let count = 0;
    entries.forEach(entry => {
        if (entry.status === 'done' && entry.suggestedName && entry.suggestedName !== entry.originalName) {
            // ren "old_name.pdf" "new_name.pdf"
            // We use simple quotes to handle spaces
            lines.push(`if exist "${entry.originalName}" (`);
            lines.push(`    ren "${entry.originalName}" "${entry.suggestedName}"`);
            lines.push(`    echo [OK] ${entry.originalName} -^> ${entry.suggestedName}`);
            lines.push(`) else (`);
            lines.push(`    echo [ERRO] Arquivo nao encontrado: ${entry.originalName}`);
            lines.push(`)`);
            count++;
        }
    });

    lines.push('echo.');
    lines.push(`echo Concluido! ${count} arquivos processados.`);
    lines.push('pause');
    return lines.join('\r\n');
}

/**
 * Generates a Shell script (Linux/Mac) content to rename files.
 */
export function generateRenameSh(entries: LibraryEntry[]): string {
    const lines = [
      '#!/bin/bash', 
      'echo "Renomeando Arquivos..."'
    ];

    entries.forEach(entry => {
        if (entry.status === 'done' && entry.suggestedName && entry.suggestedName !== entry.originalName) {
             lines.push(`mv "${entry.originalName}" "${entry.suggestedName}"`);
        }
    });

    lines.push('echo "Concluido!"');
    return lines.join('\n');
}

import React, { useState, useRef } from 'react';
import { FolderOpen, AlertCircle, HardDrive, UploadCloud } from 'lucide-react';
import { LibraryEntry } from '../types';
import { processHandle, processFileList } from '../utils/fileSystem';

interface FileUploadProps {
  onEntriesLoaded: (entries: LibraryEntry[]) => void;
  disabled?: boolean;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onEntriesLoaded, disabled }) => {
  const [isLoading, setIsLoading] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Ref for the fallback input element
  const inputRef = useRef<HTMLInputElement>(null);

  // --- Native Directory Picker ---
  const handleDirectoryPick = async () => {
    setError(null);
    setIsLoading(true);

    try {
      let successViaHandle = false;

      // Check for iframe environment which blocks File System Access API
      const isIframe = (() => {
        try {
          return window.self !== window.top;
        } catch (e) {
          return true;
        }
      })();

      // Only attempt showDirectoryPicker if NOT in an iframe
      // @ts-ignore
      if (!isIframe && typeof window.showDirectoryPicker === 'function') {
         try {
            // @ts-ignore
            const dirHandle = await window.showDirectoryPicker({
              id: 'rpg-library',
              mode: 'readwrite' 
            });

            const entries = await processHandle(dirHandle);

            if (entries.length === 0) {
              throw new Error("Nenhum arquivo PDF encontrado nesta pasta ou subpastas.");
            } else {
              onEntriesLoaded(entries);
              successViaHandle = true;
            }
         } catch (nativeErr: any) {
            // AbortError means user closed the dialog manually
            if (nativeErr.name === 'AbortError') {
              setIsLoading(false);
              return;
            }

            // Log security errors but continue to fallback
            console.warn("Acesso nativo ao sistema de arquivos falhou ou foi cancelado. Usando fallback.", nativeErr);
         }
      } else if (isIframe) {
          console.log("Ambiente Iframe detectado: pulando tentativa de File System Access API para evitar erros.");
      }

      // Fallback: Use standard <input> if native handle failed, isn't available, or we are in an iframe
      if (!successViaHandle) {
        if (inputRef.current) {
          // Clear value to ensure change event fires even if same directory selected
          inputRef.current.value = '';
          inputRef.current.click();
        } else {
          throw new Error("Input de arquivo não disponível.");
        }
      }

    } catch (err: any) {
      console.error(err);
      setError(err.message || "Erro ao ler diretório.");
    } finally {
      // Ensure loading state is reset. 
      // If falling back to input, this stops the 'initial' spinner. 
      // The input's onChange will restart loading if files are selected.
      setIsLoading(false);
    }
  };

  // --- Drag and Drop Handlers (With Handle Support) ---
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    if (!disabled) setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = async (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (disabled) return;

    setIsLoading(true);
    setError(null);

    try {
      const entries: LibraryEntry[] = [];
      const items = e.dataTransfer.items;

      if (items) {
        // Modern Way: getAsFileSystemHandle (Supports Write Access if supported)
        const promises: Promise<LibraryEntry[]>[] = [];

        for (let i = 0; i < items.length; i++) {
          const item = items[i];
          // @ts-ignore
          if (typeof item.getAsFileSystemHandle === 'function') {
            try {
              // @ts-ignore
              const handlePromise = item.getAsFileSystemHandle().then(handle => {
                if (handle) {
                  return processHandle(handle);
                }
                return [];
              });
              promises.push(handlePromise);
            } catch (e) {
               console.warn("Failed to get handle from item", e);
            }
          } else if (item.kind === 'file') {
             // Fallback for items that are files but browser doesn't support getAsFileSystemHandle
             const file = item.getAsFile();
             if (file) {
                // Wrap as list to reuse fallback logic
                const list = new DataTransfer();
                list.items.add(file);
                const fallbackEntries = processFileList(list.files);
                entries.push(...fallbackEntries);
             }
          }
        }

        const results = await Promise.all(promises);
        results.forEach(res => entries.push(...res));
      } else {
        // Legacy Drop
        entries.push(...processFileList(e.dataTransfer.files));
      }

      if (entries.length === 0) {
        setError("Nenhum PDF encontrado nos itens soltos.");
      } else {
        onEntriesLoaded(entries);
      }
    } catch (err: any) {
      console.error(err);
      setError("Erro ao processar arquivos arrastados.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleInputFiles = (e: React.ChangeEvent<HTMLInputElement>) => {
    setIsLoading(true);
    if (e.target.files && e.target.files.length > 0) {
      const entries = processFileList(e.target.files);
      if (entries.length === 0) {
        setError("Nenhum arquivo PDF encontrado.");
      } else {
        onEntriesLoaded(entries);
      }
    }
    setIsLoading(false);
    e.target.value = '';
  };

  return (
    <div className="w-full max-w-xl mx-auto">
      <input
        ref={inputRef}
        type="file"
        accept=".pdf"
        multiple
        className="hidden"
        onChange={handleInputFiles}
        // @ts-ignore
        webkitdirectory=""
        directory="" 
      />

      <div
        onClick={!disabled && !isLoading ? handleDirectoryPick : undefined}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        className={`
          relative group cursor-pointer
          border-2 border-dashed rounded-2xl p-10 transition-all duration-300 ease-in-out
          flex flex-col items-center justify-center text-center
          ${isDragging 
            ? 'border-brand-500 bg-brand-50 scale-[1.02] shadow-lg' 
            : isLoading
              ? 'border-brand-300 bg-brand-50 cursor-wait'
              : 'border-slate-300 hover:border-brand-400 hover:bg-slate-50 bg-white'
          }
          ${disabled ? 'opacity-50 cursor-not-allowed grayscale' : ''}
        `}
      >
        <div className={`
          p-4 rounded-full mb-4 transition-colors duration-300
          ${isDragging ? 'bg-brand-500 text-white' : isLoading ? 'bg-brand-100 animate-pulse text-brand-600' : 'bg-slate-100 text-slate-500 group-hover:bg-brand-50 group-hover:text-brand-500'}
        `}>
          {isLoading ? <HardDrive size={32} /> : isDragging ? <UploadCloud size={32} /> : <FolderOpen size={32} />}
        </div>

        <h3 className="text-lg font-semibold text-slate-700 mb-1">
          {isLoading ? 'Lendo arquivos...' : isDragging ? 'Solte para carregar' : 'Selecionar Pasta ou Arrastar'}
        </h3>
        <p className="text-sm text-slate-500 max-w-xs leading-relaxed">
          Clique para selecionar a pasta raiz ou <span className="font-semibold text-brand-600">arraste pastas e arquivos</span> aqui.
        </p>
      </div>

      {error && (
        <div className="mt-4 p-3 bg-red-50 border border-red-200 rounded-lg flex items-center gap-2 text-red-600 text-sm animate-fade-in">
          <AlertCircle size={16} />
          <span>{error}</span>
        </div>
      )}

      <div className="mt-6 text-center">
        <p className="text-[10px] text-slate-400 max-w-md mx-auto">
           Para renomear arquivos automaticamente, use o Chrome/Edge e aceite a permissão de edição quando solicitado, ou arraste os arquivos para esta área.
        </p>
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { BrainCircuit, Sparkles, Loader2, Plus, HardDrive, Upload, RefreshCw } from 'lucide-react';
import { AppState, LibraryEntry, FilterState, RegistryRecord, LogEntry } from './types';
import { fileToBase64 } from './utils/fileUtils';
import { renameFileOnDisk, generateRenameBat } from './utils/fileSystem';
import { analyzeRpgPdf } from './services/geminiService';
import { FileUpload } from './components/FileUpload';
import { Dashboard } from './components/Dashboard';

const App: React.FC = () => {
  const [library, setLibrary] = useState<LibraryEntry[]>([]);
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [isRenaming, setIsRenaming] = useState(false);

  // State for Resume/Import feature
  const [registryDB, setRegistryDB] = useState<Map<string, RegistryRecord>>(new Map());
  const [importedCount, setImportedCount] = useState<number>(0);
  const importInputRef = useRef<HTMLInputElement>(null);

  const [filters, setFilters] = useState<FilterState>({
    section: 'Todas',
    system: 'Todos',
    type: 'Todos',
    search: ''
  });

  // --- Helper to Append Logs ---
  const addLog = (entry: LibraryEntry, action: LogEntry['action'], message: string): LibraryEntry => {
    return {
      ...entry,
      logs: [
        ...(entry.logs || []), 
        { timestamp: new Date().toISOString(), action, message }
      ]
    };
  };

  // --- File Processing Logic (AI Analysis) ---
  const processFile = useCallback(async (entry: LibraryEntry) => {
    if (entry.isManualOverride || entry.status === 'renamed' || entry.status === 'done') return;

    try {
      const base64 = await fileToBase64(entry.file);
      const metadata = await analyzeRpgPdf(base64, entry.originalName);

      // Extract and Pad Edition Number (e.g., "1" -> "001")
      const editionRaw = (metadata.magazine_edition || "000").replace(/\D/g, '');
      const edition = editionRaw.padStart(3, '0');

      const slug = (metadata.filename_slug || "Unknown").replace(/[^a-zA-Z0-9_]/g, '');

      // Strict Naming Rule: DB_{Edition}_{Slug}.pdf
      const newName = `DB_${edition}_${slug}.pdf`;

      setLibrary(prev => prev.map(item => {
        if (item.id === entry.id) {
          const updated = addLog(item, 'ANALYZE', `DB ${edition} [${metadata.rpg_system}] (${metadata.content_type}) - ${metadata.official_title}`);
          return { ...updated, status: 'done', metadata, suggestedName: newName };
        }
        return item;
      }));

    } catch (error: any) {
      console.error(`Error processing ${entry.originalName}:`, error);
      setLibrary(prev => prev.map(item => {
        if (item.id === entry.id) {
          const updated = addLog(item, 'ERROR', error.message || "Erro na análise");
          return { ...updated, status: 'error', error: error.message };
        }
        return item;
      }));
    } finally {
      setProcessingQueue(prev => prev.filter(id => id !== entry.id));
    }
  }, []);

  // --- Queue Management (Concurrency optimized to 3) ---
  useEffect(() => {
    const CONCURRENCY_LIMIT = 3;
    const processingCount = library.filter(item => item.status === 'analyzing').length;

    if (processingCount < CONCURRENCY_LIMIT) {
      const nextItems = library
        .filter(item => item.status === 'pending' && !processingQueue.includes(item.id))
        .slice(0, CONCURRENCY_LIMIT - processingCount);

      if (nextItems.length > 0) {
        const nextIds = nextItems.map(i => i.id);
        setProcessingQueue(prev => [...prev, ...nextIds]);

        // Mark as analyzing immediately to prevent double selection in next render
        setLibrary(prev => prev.map(i => nextIds.includes(i.id) ? { ...i, status: 'analyzing' } : i));

        // Trigger process
        nextItems.forEach(item => processFile(item));
      }
    }
  }, [library, processingQueue, processFile]);

  // --- Actions: Rename, Manual Edit, Retry, Reset ---

  const handleManualEdit = (id: string, newName: string) => {
    setLibrary(prev => prev.map(item => {
      if (item.id === id) {
        const updated = addLog(item, 'EDIT', `Nome editado manualmente de '${item.suggestedName}' para '${newName}'`);
        return {
          ...updated,
          suggestedName: newName,
          isManualOverride: true,
          status: 'done' 
        };
      }
      return item;
    }));
  };

  const handleSingleRename = async (id: string) => {
    const item = library.find(i => i.id === id);
    if (!item || !item.handle) {
      alert("Arquivo não acessível para escrita.");
      return;
    }

    try {
      await renameFileOnDisk(item);
      setLibrary(prev => prev.map(i => {
        if (i.id === id) {
          const updated = addLog(i, 'RENAME', `Renomeado individualmente para ${i.suggestedName}`);
          return { ...updated, status: 'renamed' };
        }
        return i;
      }));
    } catch (e: any) {
      console.error(`Erro ao renomear ${item.originalName}:`, e);
      alert(`Erro: ${e.message}`);
      setLibrary(prev => prev.map(i => {
        if (i.id === id) return addLog(i, 'ERROR', `Falha ao renomear: ${e.message}`);
        return i;
      }));
    }
  };

  const handleRenameBatch = async () => {
    const canRename = library.some(i => i.handle !== null);

    if (!canRename) {
      const confirmDownload = window.confirm(
        "⚠️ Modo de Leitura Detectado\n\n" +
        "O navegador bloqueou o acesso de escrita ao disco (comum em iframes, CodeSandbox ou conexões sem HTTPS).\n\n" +
        "Deseja baixar um script (.bat) para renomear os arquivos automaticamente no seu computador?"
      );

      if (confirmDownload) {
          const scriptContent = generateRenameBat(library);
          const blob = new Blob([scriptContent], { type: 'text/plain' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = 'renomear_dragao_brasil.bat';
          document.body.appendChild(a);
          a.click();
          document.body.removeChild(a);

          // Mark visually as processed for better UX
          setLibrary(prev => prev.map(i => {
            if (i.status === 'done') {
                return { ...i, status: 'renamed', logs: [...i.logs, { timestamp: new Date().toISOString(), action: 'RENAME', message: 'Script de renomeação gerado.' }] };
            }
            return i;
          }));
      }
      return;
    }

    const toRename = library.filter(i => i.status === 'done' && i.suggestedName !== i.originalName);
    if (toRename.length === 0) return;

    if (!window.confirm(`Isso renomeará ${toRename.length} arquivos permanentemente. Deseja continuar?`)) return;

    setIsRenaming(true);

    for (const item of toRename) {
      try {
        await renameFileOnDisk(item);

        setLibrary(prev => prev.map(i => {
           if (i.id === item.id) {
             const updated = addLog(i, 'RENAME', `Renomeado em lote para ${i.suggestedName}`);
             return { ...updated, status: 'renamed' };
           }
           return i;
        }));

      } catch (e: any) {
        console.error(`Falha ao renomear ${item.originalName}:`, e);
        setLibrary(prev => prev.map(i => {
           if (i.id === item.id) {
             return addLog(i, 'ERROR', `Falha ao renomear: ${e.message}`);
           }
           return i;
        }));
      }
    }
    setIsRenaming(false);
  };

  const handleRetryErrors = () => {
    setLibrary(prev => prev.map(item => 
      item.status === 'error' 
        ? { ...item, status: 'pending', error: undefined, logs: [...item.logs, { timestamp: new Date().toISOString(), action: 'RESTORE', message: 'Tentativa de reprocessamento.'}] } 
        : item
    ));
  };

  const handleReset = () => {
    if (!window.confirm("Isso limpará toda a lista atual. Deseja continuar?")) return;
    setLibrary([]);
    setProcessingQueue([]);
    setRegistryDB(new Map());
    setImportedCount(0);
    setAppState(AppState.IDLE);
    setFilters({ section: 'Todas', system: 'Todos', type: 'Todos', search: '' });
  };

  // --- Resume / Import Logic ---
  const handleImportJSON = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (Array.isArray(json)) {
          const newRegistry = new Map<string, RegistryRecord>();
          json.forEach((record: RegistryRecord) => {
             if (record.fingerprint) {
                newRegistry.set(record.fingerprint, record);
             }
          });
          setRegistryDB(newRegistry);
          setImportedCount(newRegistry.size);
        } else {
          alert("Banco de dados JSON inválido.");
        }
      } catch (err) {
        console.error(err);
        alert("Erro ao ler o arquivo JSON.");
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleEntriesLoaded = (freshEntries: LibraryEntry[]) => {
    const dbByFilename = new Map<string, RegistryRecord>();
    registryDB.forEach(record => {
      if (record.currentName) {
        dbByFilename.set(record.currentName, record);
      }
    });

    const mergedEntries = freshEntries.map(entry => {
        // PRIORITY 1: Exact Fingerprint Match
        const fpRecord = registryDB.get(entry.fingerprint);
        if (fpRecord) {
            return {
              ...entry,
              status: fpRecord.status === 'renamed' ? 'renamed' : 'done',
              metadata: fpRecord.metadata,
              suggestedName: fpRecord.currentName,
              isManualOverride: fpRecord.isManualOverride,
              logs: [...(fpRecord.logs || []), { timestamp: new Date().toISOString(), action: 'RESTORE', message: 'Registro recuperado (Fingerprint).' }]
            } as LibraryEntry;
        }

        // PRIORITY 2: Filename Match
        const nameRecord = dbByFilename.get(entry.originalName);
        if (nameRecord) {
           return {
             ...entry,
             status: 'renamed', 
             metadata: nameRecord.metadata,
             suggestedName: nameRecord.currentName,
             isManualOverride: nameRecord.isManualOverride,
             logs: [...(nameRecord.logs || []), { timestamp: new Date().toISOString(), action: 'RESTORE', message: 'Registro recuperado (Nome de Arquivo).' }]
           } as LibraryEntry;
        }

        // New File
        return entry;
    });

    setLibrary(prev => [...prev, ...mergedEntries]);
    setAppState(AppState.DASHBOARD);
  };

  // --- Render Helpers ---

  const processingCount = library.filter(i => i.status === 'pending' || i.status === 'analyzing').length;
  const progressPercent = library.length > 0 
    ? ((library.length - processingCount) / library.length) * 100 
    : 0;

  return (
    <div className="flex flex-col h-screen bg-slate-50">

      <input 
        type="file" 
        accept=".json" 
        ref={importInputRef} 
        className="hidden" 
        onChange={handleImportJSON} 
      />

      {/* Header */}
      <nav className="w-full px-6 py-3 flex items-center justify-between border-b border-slate-200 bg-white z-50 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="bg-red-700 p-2 rounded-lg">
            <BrainCircuit className="text-white w-6 h-6" />
          </div>
          <div className="flex flex-col">
            <span className="text-lg font-bold text-slate-800 leading-tight">
              Dragão Brasil Indexer
            </span>
            <span className="text-xs text-slate-500">AI Edition</span>
          </div>
        </div>

        <div className="flex items-center gap-4">
           {processingCount > 0 && (
             <div className="flex items-center gap-3 bg-brand-50 px-3 py-1.5 rounded-full border border-brand-100">
               <Loader2 className="w-4 h-4 text-brand-600 animate-spin" />
               <div className="flex flex-col min-w-[120px]">
                 <span className="text-xs font-semibold text-brand-700">Indexando... {library.length - processingCount}/{library.length}</span>
                 <div className="w-full bg-brand-200 rounded-full h-1 mt-1">
                   <div className="bg-brand-500 h-1 rounded-full transition-all duration-300" style={{ width: `${progressPercent}%` }}></div>
                 </div>
               </div>
             </div>
           )}
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden p-6 max-w-[1600px] w-full mx-auto">

        {appState === AppState.IDLE ? (
          <div className="h-full flex flex-col items-center justify-center animate-fade-in-up">
            <div className="text-center space-y-6 max-w-2xl">
              <h1 className="text-4xl font-extrabold text-slate-900">
                Organize sua coleção da <br/>
                <span className="text-red-700">Dragão Brasil.</span>
              </h1>

              {importedCount === 0 ? (
                 <>
                    <p className="text-lg text-slate-600">
                      Selecione a pasta onde estão seus PDFs da revista. A IA identificará a edição e a coluna automaticamente.
                    </p>
                    <div className="bg-yellow-50 border border-yellow-200 p-4 rounded-lg text-sm text-yellow-800 text-left mx-auto max-w-lg">
                      <strong>Nota:</strong> A renomeação automática (DB_000_Slug.pdf) requer suporte a API de Sistema de Arquivos (Chrome/Edge).
                    </div>
                 </>
              ) : (
                 <div className="bg-green-50 border border-green-200 p-6 rounded-xl animate-fade-in text-left mx-auto max-w-xl shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                      <div className="p-2 bg-green-100 rounded-full text-green-600">
                        <RefreshCw size={24} />
                      </div>
                      <h3 className="text-lg font-bold text-green-800">Database Carregado!</h3>
                    </div>
                    <p className="text-green-700 mb-4">
                      {importedCount} registros históricos identificados.
                    </p>
                 </div>
              )}

              <div className="pt-4 w-full max-w-xl mx-auto space-y-4">
                <FileUpload onEntriesLoaded={handleEntriesLoaded} />

                {importedCount === 0 && (
                  <button 
                    onClick={() => importInputRef.current?.click()}
                    className="flex items-center justify-center gap-2 w-full py-3 text-slate-500 hover:text-brand-600 hover:bg-slate-100 rounded-lg transition-colors text-sm font-medium border border-transparent hover:border-slate-200"
                  >
                    <Upload size={16} />
                    Carregar Database (.json)
                  </button>
                )}
              </div>
            </div>
          </div>
        ) : (
          <Dashboard 
            library={library} 
            filters={filters} 
            setFilters={setFilters} 
            onRenameClick={handleRenameBatch}
            onRetryClick={handleRetryErrors}
            onResetClick={handleReset}
            onManualEdit={handleManualEdit}
            onSingleRename={handleSingleRename}
            isRenaming={isRenaming}
          />
        )}

      </main>
    </div>
  );
};

